insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-01', 2027, 1, 'Notice the little things', 'Attention', 'A year begins quietly. Before doing anything ambitious, we start by looking: the light on a wall, a stranger''s kindness, the sound a kettle makes. Noticing is a skill, and like most skills it gets easier with a little practice.', '["On any day this month, write down one thing you noticed that you might normally walk past.", "One observation counts per day. Seven different days completes the month.", "Entries are private and stay yours. A sentence is plenty."]'::jsonb, 7, 'days', 'reflection', 'distinctDays', 'observation', null, make_timestamptz(2027, 1, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-01", "year": 2027, "month": 1, "title": "Notice the little things", "tagline": "Seven small observations, on seven different days.", "category": "Attention", "story": "A year begins quietly. Before doing anything ambitious, we start by looking: the light on a wall, a stranger''s kindness, the sound a kettle makes. Noticing is a skill, and like most skills it gets easier with a little practice.", "why": "Writing down one thing you noticed is a simple way to practise paying attention. It asks nothing of you except a moment.", "instructions": ["On any day this month, write down one thing you noticed that you might normally walk past.", "One observation counts per day. Seven different days completes the month.", "Entries are private and stay yours. A sentence is plenty."], "safetyNote": null, "target": 7, "unit": "days", "module": "reflection", "metric": "distinctDays", "entryKind": "observation", "minimumAmount": null, "prompts": ["What did you notice today that you''d usually miss?", "What was the light like today?", "What small sound stood out?", "What did someone do today that was quietly kind?", "What looked different from yesterday?", "What did you enjoy for a few seconds today?", "What detail would you put in a painting of today?"], "accessibleAlternative": null, "symbol": "eye", "accent": "sage", "reflectionPrompt": "Which observation surprised you most when you read it back?", "completionLine": "January is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-02', 2027, 2, 'Give your brain a workout', 'Mind', 'Nine rows, nine columns, nine squares, and one rule. Sudoku needs no arithmetic and no general knowledge, only patience and a willingness to rule things out. February is short; five puzzles fit it nicely.', '["Each row, column and 3×3 square must contain the numbers 1–9 exactly once.", "Solve five different puzzles this month. Your place is saved automatically, so stop whenever you like.", "Pencil marks and hints are there to be used. A hinted puzzle still counts."]'::jsonb, 5, 'puzzles', 'sudoku', 'distinctRefs', 'sudoku_solved', null, make_timestamptz(2027, 2, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-02", "year": 2027, "month": 2, "title": "Give your brain a workout", "tagline": "Solve five medium-to-hard Sudoku puzzles.", "category": "Mind", "story": "Nine rows, nine columns, nine squares, and one rule. Sudoku needs no arithmetic and no general knowledge, only patience and a willingness to rule things out. February is short; five puzzles fit it nicely.", "why": "A little exercise for the part of your mind that likes figuring things out. Sudoku is practice in logical reasoning, working through constraints, and staying with a problem.", "instructions": ["Each row, column and 3×3 square must contain the numbers 1–9 exactly once.", "Solve five different puzzles this month. Your place is saved automatically, so stop whenever you like.", "Pencil marks and hints are there to be used. A hinted puzzle still counts."], "safetyNote": null, "target": 5, "unit": "puzzles", "module": "sudoku", "metric": "distinctRefs", "entryKind": "sudoku_solved", "minimumAmount": null, "prompts": [], "accessibleAlternative": null, "symbol": "square.grid.3x3", "accent": "gold", "reflectionPrompt": "Was there a moment a puzzle suddenly opened up? What changed?", "completionLine": "February is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-03', 2027, 3, 'Build your core', 'Body', 'Not thirty minutes at once — thirty minutes in total, in whatever pieces suit you. Twenty seconds here, a minute there. By the end of March those small holds add up to something you can feel.', '["Start the timer, hold a plank for as long as feels steady, then pause or finish.", "Rest as often as you like. Only time on the clock counts; paused time never does.", "Reach 30 minutes in total before the month ends."]'::jsonb, 30, 'minutes', 'timer', 'sumMinutes', 'plank', null, make_timestamptz(2027, 3, 1, 0, 0, 0, 'Pacific/Kiritimati'), '{"title": "Seated core hold", "detail": "Sit tall near the front of a chair, feet flat, and gently draw your stomach in while you breathe steadily. Lean back a few degrees if comfortable. It counts minute for minute, exactly like a plank."}'::jsonb, '{"id": "2027-03", "year": 2027, "month": 3, "title": "Build your core", "tagline": "Thirty minutes of planking, added up across the month.", "category": "Body", "story": "Not thirty minutes at once — thirty minutes in total, in whatever pieces suit you. Twenty seconds here, a minute there. By the end of March those small holds add up to something you can feel.", "why": "Short, regular holds are a simple way to practise core strength and body awareness. The month rewards showing up, not straining.", "instructions": ["Start the timer, hold a plank for as long as feels steady, then pause or finish.", "Rest as often as you like. Only time on the clock counts; paused time never does.", "Reach 30 minutes in total before the month ends."], "safetyNote": "Keep a straight line from shoulders to heels and breathe normally. Stop if you feel pain, dizziness or discomfort; rest is part of the practice. If you have an injury or a health condition, check with a professional first.", "target": 30, "unit": "minutes", "module": "timer", "metric": "sumMinutes", "entryKind": "plank", "minimumAmount": null, "prompts": [], "accessibleAlternative": {"title": "Seated core hold", "detail": "Sit tall near the front of a chair, feet flat, and gently draw your stomach in while you breathe steadily. Lean back a few degrees if comfortable. It counts minute for minute, exactly like a plank."}, "symbol": "figure.core.training", "accent": "terracotta", "reflectionPrompt": "How did the first session compare with the last?", "completionLine": "March is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-04', 2027, 4, 'Find beauty in the ordinary', 'Creativity', 'A door handle worn smooth. Shadows of a fence. Fruit in a bowl. April asks you to look at ordinary things as if they had been placed there on purpose, and to keep ten of them.', '["Take or choose a photo of an everyday detail you find quietly beautiful.", "Add a caption if you''d like to remember why.", "Collect ten this month. Photos stay on your iPhone."]'::jsonb, 10, 'photos', 'photos', 'count', 'photo', null, make_timestamptz(2027, 4, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-04", "year": 2027, "month": 4, "title": "Find beauty in the ordinary", "tagline": "Ten photos of everyday details most people overlook.", "category": "Creativity", "story": "A door handle worn smooth. Shadows of a fence. Fruit in a bowl. April asks you to look at ordinary things as if they had been placed there on purpose, and to keep ten of them.", "why": "Looking for something worth photographing changes how a familiar place feels. It''s practice in seeing.", "instructions": ["Take or choose a photo of an everyday detail you find quietly beautiful.", "Add a caption if you''d like to remember why.", "Collect ten this month. Photos stay on your iPhone."], "safetyNote": null, "target": 10, "unit": "photos", "module": "photos", "metric": "count", "entryKind": "photo", "minimumAmount": null, "prompts": [], "accessibleAlternative": null, "symbol": "camera.macro", "accent": "sage", "reflectionPrompt": "Which of the ten would you hang on a wall?", "completionLine": "April is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-05', 2027, 5, 'Read a little further', 'Mind', 'Sixty pages is a few evenings, or two pages a day. It can be a novel you abandoned, a book someone gave you, or something you have always meant to start. May is for getting a little further in.', '["Tell us what you''re reading. More than one book is fine.", "Log the pages you read whenever you put the book down.", "Sixty pages in total completes the month."]'::jsonb, 60, 'pages', 'reading', 'sumAmount', 'reading', null, make_timestamptz(2027, 5, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-05", "year": 2027, "month": 5, "title": "Read a little further", "tagline": "Read and log sixty pages of a book.", "category": "Mind", "story": "Sixty pages is a few evenings, or two pages a day. It can be a novel you abandoned, a book someone gave you, or something you have always meant to start. May is for getting a little further in.", "why": "Reading a book asks for a different kind of attention than a screen does. Sixty pages is enough to remember what that feels like.", "instructions": ["Tell us what you''re reading. More than one book is fine.", "Log the pages you read whenever you put the book down.", "Sixty pages in total completes the month."], "safetyNote": null, "target": 60, "unit": "pages", "module": "reading", "metric": "sumAmount", "entryKind": "reading", "minimumAmount": null, "prompts": [], "accessibleAlternative": null, "symbol": "book", "accent": "gold", "reflectionPrompt": "What''s one line or idea from your reading that stayed with you?", "completionLine": "May is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-06', 2027, 6, 'Learn another language', 'Curiosity', 'Twelve words will not make you fluent. They will let you greet someone, thank them, and ask for bread — which is how every language begins. Pick one and make a small start.', '["Choose a language and study its twelve words with the flashcards.", "Listen to each word, then practise until they feel familiar.", "Pass the recall exercise — at least 10 of 12 — to complete the month. You can retake it as often as you like."]'::jsonb, 12, 'words', 'vocabulary', 'vocabulary', 'word_learned', null, make_timestamptz(2027, 6, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-06", "year": 2027, "month": 6, "title": "Learn another language", "tagline": "Learn twelve words and show you can recall them.", "category": "Curiosity", "story": "Twelve words will not make you fluent. They will let you greet someone, thank them, and ask for bread — which is how every language begins. Pick one and make a small start.", "why": "Learning a handful of words in another language is a friendly way to practise memory, and a small courtesy to the people who speak it.", "instructions": ["Choose a language and study its twelve words with the flashcards.", "Listen to each word, then practise until they feel familiar.", "Pass the recall exercise — at least 10 of 12 — to complete the month. You can retake it as often as you like."], "safetyNote": null, "target": 12, "unit": "words", "module": "vocabulary", "metric": "vocabulary", "entryKind": "word_learned", "minimumAmount": null, "prompts": [], "accessibleAlternative": null, "symbol": "character.bubble", "accent": "terracotta", "reflectionPrompt": "Which word are you most likely to actually use?", "completionLine": "June is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-07', 2027, 7, 'Do something good', 'Kindness', 'Hold a door. Send the message you''ve been meaning to send. Let someone go first. July is for five small, deliberate kindnesses — and for noticing how they felt.', '["Do something kind for someone — small is fine.", "Afterwards, write a line about what you did. It stays private.", "Five entries complete the month."]'::jsonb, 5, 'acts', 'reflection', 'count', 'kindness', null, make_timestamptz(2027, 7, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-07", "year": 2027, "month": 7, "title": "Do something good", "tagline": "Record five acts of kindness.", "category": "Kindness", "story": "Hold a door. Send the message you''ve been meaning to send. Let someone go first. July is for five small, deliberate kindnesses — and for noticing how they felt.", "why": "Kindness is easy to intend and easy to forget. Writing it down afterwards makes it a little more likely to happen again.", "instructions": ["Do something kind for someone — small is fine.", "Afterwards, write a line about what you did. It stays private.", "Five entries complete the month."], "safetyNote": null, "target": 5, "unit": "acts", "module": "reflection", "metric": "count", "entryKind": "kindness", "minimumAmount": null, "prompts": ["What did you do, and for whom?", "What small thing made someone''s day easier?", "Who did you check in on?", "What did you give — time, attention, help?"], "accessibleAlternative": null, "symbol": "heart", "accent": "terracotta", "reflectionPrompt": "Which of these would you like to make a habit?", "completionLine": "July is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-08', 2027, 8, 'Make something new', 'Creativity', 'It doesn''t have to be elaborate. A salad dressing from scratch, a flatbread, a soup from whatever''s in season. August is for three small firsts in the kitchen.', '["Choose something you''ve never prepared. Simple recipes count.", "Make it, then log its name. Add a photo or a note if you like.", "Three new dishes complete the month."]'::jsonb, 3, 'dishes', 'reflection', 'count', 'dish', null, make_timestamptz(2027, 8, 1, 0, 0, 0, 'Pacific/Kiritimati'), '{"title": "No-cook or assisted recipes", "detail": "Assembling counts as much as cooking: a new sandwich, a fruit plate, a cold drink, or a dish made together with someone else."}'::jsonb, '{"id": "2027-08", "year": 2027, "month": 8, "title": "Make something new", "tagline": "Prepare three dishes you''ve never made before.", "category": "Creativity", "story": "It doesn''t have to be elaborate. A salad dressing from scratch, a flatbread, a soup from whatever''s in season. August is for three small firsts in the kitchen.", "why": "Making something you haven''t made before is a low-stakes way to practise following your curiosity — and you get to eat the result.", "instructions": ["Choose something you''ve never prepared. Simple recipes count.", "Make it, then log its name. Add a photo or a note if you like.", "Three new dishes complete the month."], "safetyNote": null, "target": 3, "unit": "dishes", "module": "reflection", "metric": "count", "entryKind": "dish", "minimumAmount": null, "prompts": ["What did you make?", "What was new about it for you?", "How did it turn out?"], "accessibleAlternative": {"title": "No-cook or assisted recipes", "detail": "Assembling counts as much as cooking: a new sandwich, a fruit plate, a cold drink, or a dish made together with someone else."}, "symbol": "fork.knife", "accent": "gold", "reflectionPrompt": "Which dish would you make again, and what would you change?", "completionLine": "August is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-09', 2027, 9, 'Get moving', 'Body', 'Two hours across a whole month: a few loops of the block, a longer route home, a walk with a friend. The only rule is that you set out on purpose.', '["Start the timer when you set out and finish it when you''re done.", "Walks can be any length. They add up across the month.", "Reach 120 minutes in total. No location is ever recorded."]'::jsonb, 120, 'minutes', 'timer', 'sumMinutes', 'walk', null, make_timestamptz(2027, 9, 1, 0, 0, 0, 'Pacific/Kiritimati'), '{"title": "Any intentional movement", "detail": "Wheeling, gentle stretching, chair exercises, swimming or any movement you choose on purpose counts minute for minute."}'::jsonb, '{"id": "2027-09", "year": 2027, "month": 9, "title": "Get moving", "tagline": "One hundred and twenty minutes of intentional walking.", "category": "Body", "story": "Two hours across a whole month: a few loops of the block, a longer route home, a walk with a friend. The only rule is that you set out on purpose.", "why": "Walking on purpose, without it being the way to somewhere else, encourages intentional movement and a little time with your own thoughts.", "instructions": ["Start the timer when you set out and finish it when you''re done.", "Walks can be any length. They add up across the month.", "Reach 120 minutes in total. No location is ever recorded."], "safetyNote": "Go at a pace that lets you talk comfortably, and stop if anything hurts.", "target": 120, "unit": "minutes", "module": "timer", "metric": "sumMinutes", "entryKind": "walk", "minimumAmount": null, "prompts": [], "accessibleAlternative": {"title": "Any intentional movement", "detail": "Wheeling, gentle stretching, chair exercises, swimming or any movement you choose on purpose counts minute for minute."}, "symbol": "figure.walk", "accent": "sage", "reflectionPrompt": "Where did your favourite walk take you?", "completionLine": "September is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-10', 2027, 10, 'Make something from nothing', 'Creativity', 'A poem, a sketch, a song, a shelf, a short film on your phone. October gives you three steps: choose an idea, make a rough first version, then improve or finish it. Finished beats perfect.', '["Stage one: write down the idea you''ve chosen.", "Stage two: make a first version and record it with a note or a photo.", "Stage three: improve or finish it, and record what changed."]'::jsonb, 3, 'stages', 'creative', 'distinctRefs', 'creative_stage', null, make_timestamptz(2027, 10, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-10", "year": 2027, "month": 10, "title": "Make something from nothing", "tagline": "Take one creative project through three stages.", "category": "Creativity", "story": "A poem, a sketch, a song, a shelf, a short film on your phone. October gives you three steps: choose an idea, make a rough first version, then improve or finish it. Finished beats perfect.", "why": "Most ideas stall before the first rough version. Three small stages are a gentle way to practise getting past that.", "instructions": ["Stage one: write down the idea you''ve chosen.", "Stage two: make a first version and record it with a note or a photo.", "Stage three: improve or finish it, and record what changed."], "safetyNote": null, "target": 3, "unit": "stages", "module": "creative", "metric": "distinctRefs", "entryKind": "creative_stage", "minimumAmount": null, "prompts": [], "accessibleAlternative": null, "symbol": "paintbrush.pointed", "accent": "gold", "reflectionPrompt": "What did the second version teach you that the first didn''t?", "completionLine": "October is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-11', 2027, 11, 'Take back your attention', 'Attention', 'Ten minutes, one thing, nothing else. Read, write, think, practise, tidy a drawer — anything you choose to give your full attention. Do it ten times this month.', '["Decide what you''ll focus on, then start the ten-minute timer.", "Put your phone face down. A sound and a notification mark the end.", "A session counts when the full ten minutes are complete. Ten sessions complete the month."]'::jsonb, 10, 'sessions', 'focus', 'qualifyingSessions', 'focus', 600, make_timestamptz(2027, 11, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-11", "year": 2027, "month": 11, "title": "Take back your attention", "tagline": "Ten focused sessions of ten minutes each.", "category": "Attention", "story": "Ten minutes, one thing, nothing else. Read, write, think, practise, tidy a drawer — anything you choose to give your full attention. Do it ten times this month.", "why": "Ten uninterrupted minutes is short enough to start and long enough to notice the pull of distraction. It''s practice in sustained attention.", "instructions": ["Decide what you''ll focus on, then start the ten-minute timer.", "Put your phone face down. A sound and a notification mark the end.", "A session counts when the full ten minutes are complete. Ten sessions complete the month."], "safetyNote": null, "target": 10, "unit": "sessions", "module": "focus", "metric": "qualifyingSessions", "entryKind": "focus", "minimumAmount": 600, "prompts": [], "accessibleAlternative": null, "symbol": "scope", "accent": "sage", "reflectionPrompt": "What did you do with your best ten minutes?", "completionLine": "November is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.challenge_definitions (id, year, month, title, category, story, instructions, completion_target, unit, module_type, metric, entry_kind, minimum_amount, reveal_at, accessible_alternatives, editorial, editorial_version) values ('2027-12', 2027, 12, 'Remember your year', 'Reflection', 'The year is nearly a memory. Before it becomes one, choose twelve moments worth keeping — large or small — and write a line about each. Then look back at everything you collected.', '["Think back over 2027 and write down a moment that mattered.", "Add a photo if you have one. Everything stays private unless you choose to share.", "Twelve moments complete the month and unlock your Year in Review."]'::jsonb, 12, 'moments', 'reflection', 'count', 'moment', null, make_timestamptz(2027, 12, 1, 0, 0, 0, 'Pacific/Kiritimati'), 'null'::jsonb, '{"id": "2027-12", "year": 2027, "month": 12, "title": "Remember your year", "tagline": "Capture twelve meaningful moments from 2027.", "category": "Reflection", "story": "The year is nearly a memory. Before it becomes one, choose twelve moments worth keeping — large or small — and write a line about each. Then look back at everything you collected.", "why": "Looking back on purpose turns a blur of months into a handful of stories you can actually tell.", "instructions": ["Think back over 2027 and write down a moment that mattered.", "Add a photo if you have one. Everything stays private unless you choose to share.", "Twelve moments complete the month and unlock your Year in Review."], "safetyNote": null, "target": 12, "unit": "moments", "module": "reflection", "metric": "count", "entryKind": "moment", "minimumAmount": null, "prompts": ["A moment from this year you want to remember…", "A day that went better than expected…", "Someone who made this year better…", "Something you did for the first time…", "A place you were glad to be…", "Something small that made you laugh…"], "accessibleAlternative": null, "symbol": "sparkles", "accent": "terracotta", "reflectionPrompt": "If you could keep only one of these twelve, which would it be?", "completionLine": "December is officially one for the books.", "version": 1}'::jsonb, 1) on conflict (id) do update set title = excluded.title, story = excluded.story, instructions = excluded.instructions, editorial = excluded.editorial, editorial_version = excluded.editorial_version where public.challenge_definitions.reveal_at > now();
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-001', 'The test that started the conversation', 'In 1950 Alan Turing opened a paper with a blunt question: can machines think? Rather than argue about definitions, he proposed a game. A judge exchanges typed messages with a person and a machine, without knowing which is which. If the judge cannot reliably tell them apart, Turing suggested, the machine deserves to be taken seriously. He called it the imitation game. We now call it the Turing test, and people still argue about what passing it would really mean.', 'technology', 'ai', 'Wikipedia: Turing test', 'https://en.wikipedia.org/wiki/Turing_test', '{"quiz": {"question": "What did Turing originally call his test?", "options": ["The Enigma trial", "The imitation game", "The thinking test"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-002', 'The chatbot from 1966', 'ELIZA was a program written at MIT by Joseph Weizenbaum in the mid-1960s. Its best-known script, DOCTOR, imitated a psychotherapist by turning a person''s own statements back into questions. It understood nothing; it simply matched patterns. Yet Weizenbaum was startled to find that people confided in it and grew attached to it, even when they knew how it worked. The tendency to read understanding into a machine''s words is still called the ELIZA effect.', 'technology', 'ai', 'Wikipedia: ELIZA', 'https://en.wikipedia.org/wiki/ELIZA', '{"quiz": {"question": "What kind of person did ELIZA''s DOCTOR script imitate?", "options": ["A librarian", "A chess master", "A psychotherapist"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-003', 'When a computer beat the world champion', 'In May 1997, IBM''s chess computer Deep Blue defeated the reigning world champion, Garry Kasparov, in a six-game match played under standard tournament time controls. Kasparov had beaten an earlier version of the machine the year before. The 1997 result, three and a half points to two and a half, was the first time a reigning champion lost a match to a computer under those conditions, and it became a landmark in the public story of computing.', 'technology', 'ai', 'Wikipedia: Deep Blue versus Garry Kasparov', 'https://en.wikipedia.org/wiki/Deep_Blue_versus_Garry_Kasparov', '{"quiz": {"question": "In which year did Deep Blue win its match against Kasparov?", "options": ["1997", "1987", "2007"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-004', 'A summer workshop named a field', 'The phrase "artificial intelligence" comes from a funding proposal. In 1955 John McCarthy and a few colleagues proposed a summer research project at Dartmouth College, to be held in 1956, on the conjecture that every aspect of learning could in principle be described so precisely that a machine could simulate it. The workshop itself was loose and informal, but the name stuck, and the meeting is widely regarded as the founding event of AI as a field.', 'technology', 'ai', 'Wikipedia: Dartmouth workshop', 'https://en.wikipedia.org/wiki/Dartmouth_workshop', '{"quiz": {"question": "Where was the 1956 workshop that gave AI its name?", "options": ["Stanford University", "Bell Labs", "Dartmouth College"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-005', 'A program written before computers existed', 'In 1843 Ada Lovelace published a translation of an article about Charles Babbage''s proposed Analytical Engine, and added notes of her own that were longer than the article. One of them, Note G, set out step by step how the machine could calculate a sequence called the Bernoulli numbers. It is often described as the first published computer program. The engine was never completed, so the program was never run in her lifetime.', 'technology', 'ai', 'Wikipedia: Ada Lovelace', 'https://en.wikipedia.org/wiki/Ada_Lovelace', '{"quiz": {"question": "Which machine was Ada Lovelace writing about?", "options": ["ENIAC", "The Analytical Engine", "The Enigma machine"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-006', 'The machine that learned from mistakes', 'In 1958 the psychologist Frank Rosenblatt demonstrated the perceptron, a simple model of a neuron that could learn to sort inputs into two groups by adjusting its own weights after each error. Newspapers of the day predicted thinking machines within years. The perceptron turned out to have real limits, and enthusiasm faded for a time. But the core idea — learning by nudging numbers after mistakes — sits underneath the neural networks used today.', 'technology', 'ai', 'Wikipedia: Perceptron', 'https://en.wikipedia.org/wiki/Perceptron', '{"quiz": null, "prompt": "Think of something you learned by trial and error. How many tries did it take?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-007', 'Why the save icon is still a floppy disk', 'Floppy disks were once how most people stored and moved their files, so early software used a picture of one to mean "save". The disks themselves have long since disappeared from everyday computers, yet the little square with a notch survives in toolbars. Many people who press it have never held the real thing. It''s a reminder that an icon can outlive the object it was drawn from.', 'technology', 'products', 'Wikipedia: Floppy disk', 'https://en.wikipedia.org/wiki/Floppy_disk', '{"quiz": null, "prompt": "Look at your phone. Which other icons picture an object you no longer use?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-008', 'The mouse was made of wood', 'The first computer mouse was built in 1964 by Bill English from a design by Douglas Engelbart at the Stanford Research Institute. It was a small wooden block with two metal wheels and a single button. Engelbart showed it to the public in December 1968, in a demonstration that also introduced on-screen windows, hypertext and video conferencing. That session is now remembered as "the Mother of All Demos".', 'technology', 'products', 'Wikipedia: Computer mouse', 'https://en.wikipedia.org/wiki/Computer_mouse', '{"quiz": {"question": "What was the first mouse''s casing made from?", "options": ["Aluminium", "Wood", "Bakelite"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-009', 'Music you could carry', 'Sony released the first Walkman, the TPS-L2, in Japan in July 1979. It was a cassette player that could not record and had no speaker, which some inside the company thought would doom it. Instead it sold in huge numbers and changed where music was heard: on trains, on pavements, on runs. For the first time a personal soundtrack could follow someone through a public space.', 'technology', 'products', 'Wikipedia: Walkman', 'https://en.wikipedia.org/wiki/Walkman', '{"quiz": {"question": "What did the first Walkman play?", "options": ["Cassette tapes", "Compact discs", "Vinyl singles"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-010', 'A king''s name on your headphones', 'Bluetooth is named after Harald Bluetooth, a tenth-century king who united parts of Denmark and Norway. An engineer suggested the name in 1997 as a temporary code name for a technology meant to unite different devices, and it was never replaced. The logo is a bind-rune that merges the king''s initials: the runes Hagall and Bjarkan.', 'technology', 'products', 'Wikipedia: Bluetooth', 'https://en.wikipedia.org/wiki/Bluetooth', '{"quiz": {"question": "What does the Bluetooth logo combine?", "options": ["Two runes", "Two Greek letters", "A B and a T"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-011', 'The keyboard layout from the 1870s', 'The QWERTY layout was developed in the early 1870s for the Sholes and Glidden typewriter, and became standard after the success of the Remington typewriters that followed. Exactly why the letters were arranged this way is still debated; one long-standing account says it helped keep the machine''s metal type bars from jamming. Whatever the reason, the layout outlasted the mechanism entirely and moved onto glass screens.', 'technology', 'products', 'Wikipedia: QWERTY', 'https://en.wikipedia.org/wiki/QWERTY', '{"quiz": null, "prompt": "Type a sentence slowly and notice which hand does more of the work.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-012', 'The phone announced in 2007', 'Steve Jobs introduced the first iPhone on 9 January 2007, describing it as three products in one: a widescreen iPod with touch controls, a mobile phone, and an internet communicator. It went on sale in the United States on 29 June that year. It had no App Store at launch — that arrived in 2008 — and it could not copy and paste text until a later software update.', 'technology', 'products', 'Wikipedia: iPhone (1st generation)', 'https://en.wikipedia.org/wiki/IPhone_(1st_generation)', '{"quiz": {"question": "What was missing from the first iPhone at launch?", "options": ["An App Store", "A touchscreen", "A camera"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-013', 'The first message was "LO"', 'On 29 October 1969 a student programmer at UCLA, Charley Kline, tried to log in to a computer at the Stanford Research Institute over the brand-new ARPANET. He meant to type LOGIN. The system crashed after the first two letters, so the first message ever sent on the network that grew into the internet was "LO". The full login worked about an hour later.', 'technology', 'internet', 'Wikipedia: ARPANET', 'https://en.wikipedia.org/wiki/ARPANET', '{"quiz": {"question": "What word was the sender trying to type?", "options": ["LOGIN", "LOOK", "LOAD"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-014', 'Why email addresses have an @', 'In 1971 the programmer Ray Tomlinson sent the first email between two different computers on the ARPANET. He needed a way to separate a person''s name from the name of their machine, and chose the @ sign from the keyboard because it was unlikely to appear in anyone''s name and already read as "at". He later said he could not remember what the first message said — probably something like a row of keys.', 'technology', 'internet', 'Wikipedia: Ray Tomlinson', 'https://en.wikipedia.org/wiki/Ray_Tomlinson', '{"quiz": {"question": "Who chose the @ sign for email?", "options": ["Vint Cerf", "Ray Tomlinson", "Tim Berners-Lee"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-015', 'The web was given away', 'Tim Berners-Lee proposed the World Wide Web in 1989 while working at CERN, the European physics laboratory, as a way for researchers to share linked documents. The first website went live there in 1991. In April 1993 CERN made the web''s underlying software freely available to everyone, with no fees. That decision is a large part of why the web spread so quickly instead of remaining one product among many.', 'technology', 'internet', 'Wikipedia: World Wide Web', 'https://en.wikipedia.org/wiki/World_Wide_Web', '{"quiz": {"question": "At which institution was the web invented?", "options": ["MIT", "NASA", "CERN"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-016', 'The first webcam watched a coffee pot', 'In 1991 researchers at the University of Cambridge''s computer laboratory pointed a camera at the coffee pot in a room called the Trojan Room, so that people working elsewhere in the building could check whether there was any coffee before making the walk. In 1993 the image was connected to the web, where it became an early online curiosity. The camera was finally switched off in 2001.', 'technology', 'internet', 'Wikipedia: Trojan Room coffee pot', 'https://en.wikipedia.org/wiki/Trojan_Room_coffee_pot', '{"quiz": {"question": "What was the first webcam pointed at?", "options": ["A car park", "A fish tank", "A coffee pot"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-017', 'Emoji began as a set of 176', 'In 1999 Shigetaka Kurita designed a set of 176 small pictures for a Japanese mobile internet service run by NTT DoCoMo. Each was drawn on a grid just twelve pixels square, and they covered weather, transport, phases of the moon and a handful of faces. The word emoji comes from the Japanese for "picture" and "character"; its resemblance to the English word emotion is a coincidence.', 'technology', 'internet', 'Wikipedia: Emoji', 'https://en.wikipedia.org/wiki/Emoji', '{"quiz": {"question": "Where does the word \"emoji\" come from?", "options": ["A company name", "Japanese for picture + character", "English emotion + icon"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-018', 'The bug that was a moth', 'On 9 September 1947, operators of the Harvard Mark II computer traced a fault to a moth trapped in a relay. They taped the insect into the logbook with the note "First actual case of bug being found". The joke only works because engineers were already calling faults "bugs" — Thomas Edison used the word that way in the 1870s. The logbook page, moth included, is kept by the Smithsonian.', 'technology', 'general', 'Wikipedia: Bug (engineering)', 'https://en.wikipedia.org/wiki/Bug_(engineering)', '{"quiz": {"question": "What insect was taped into the logbook?", "options": ["A beetle", "A moth", "A fly"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-019', 'A prediction that steered an industry', 'In 1965 Gordon Moore, later a co-founder of Intel, observed that the number of components on an integrated circuit had been doubling every year, and predicted that this would continue for a decade. In 1975 he revised the pace to a doubling about every two years. Moore''s law was never a law of nature. It was an observation that became a target, and chip makers planned around it for decades.', 'technology', 'general', 'Wikipedia: Moore''s law', 'https://en.wikipedia.org/wiki/Moore%27s_law', '{"quiz": {"question": "What does Moore''s law describe doubling?", "options": ["Internet speed", "Components on a chip", "Battery life"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('technology-020', 'Your map needs Einstein', 'GPS receivers work out where they are by comparing time signals from satellites. The clocks on those satellites do not tick at quite the same rate as clocks on the ground: moving fast slows them slightly, while weaker gravity at altitude speeds them up by more. The net effect is that they run ahead by about 38 microseconds a day. Without correcting for relativity, positions would drift by kilometres within a day.', 'technology', 'general', 'Wikipedia: Error analysis for the Global Positioning System', 'https://en.wikipedia.org/wiki/Error_analysis_for_the_Global_Positioning_System', '{"quiz": {"question": "Left uncorrected, satellite clocks would run…", "options": ["Exactly in step", "Behind ground clocks", "Ahead of ground clocks"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-001', 'The typeface that tried to say nothing', 'Helvetica was created in 1957 by Max Miedinger with Eduard Hoffmann at the Haas type foundry in Switzerland. It was first sold as Neue Haas Grotesk and renamed a few years later, after the Latin name for Switzerland, to help it sell abroad. Its designers wanted a clear, neutral typeface with no particular character of its own. That neutrality made it one of the most widely used typefaces of the twentieth century.', 'design', null, 'Wikipedia: Helvetica', 'https://en.wikipedia.org/wiki/Helvetica', '{"quiz": {"question": "What was Helvetica first called?", "options": ["Swiss Modern", "Neue Haas Grotesk", "Akzidenz"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-002', 'The map that ignored geography', 'Harry Beck was a draughtsman who, in 1931, redrew the London Underground map as a diagram. He straightened the lines, allowed only horizontal, vertical and 45-degree angles, and spaced the stations evenly regardless of the real distances between them. His reasoning was that passengers underground only need to know the order of stations and where to change. First printed for the public in 1933, it became the model for transit maps around the world.', 'design', null, 'Wikipedia: Tube map', 'https://en.wikipedia.org/wiki/Tube_map', '{"quiz": null, "prompt": "Next time you read a transit map, notice what it leaves out.", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-003', 'As little design as possible', 'Dieter Rams led design at the German company Braun for decades and summed up his approach in ten principles of good design. Good design, he wrote, is innovative, useful, aesthetic, understandable, unobtrusive, honest, long-lasting, thorough down to the last detail, environmentally friendly — and, finally, as little design as possible. His calculators, radios and shelving have been cited as an influence by many later product designers.', 'design', null, 'Wikipedia: Dieter Rams', 'https://en.wikipedia.org/wiki/Dieter_Rams', '{"quiz": null, "prompt": "Pick up an object near you. Which of its details could be removed without loss?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-004', 'A school that lasted fourteen years', 'The Bauhaus was a German school of art and design founded by the architect Walter Gropius in Weimar in 1919. It set out to bring fine art, craft and industry together, and its students worked in workshops as well as studios. The school moved to Dessau and then Berlin before closing under pressure from the Nazi regime in 1933. Its teachers scattered across the world, and carried its ideas with them.', 'design', null, 'Wikipedia: Bauhaus', 'https://en.wikipedia.org/wiki/Bauhaus', '{"quiz": {"question": "In which city was the Bauhaus founded?", "options": ["Zurich", "Vienna", "Weimar"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-005', 'Why screen corners are easy to hit', 'In 1954 the psychologist Paul Fitts described a relationship now known as Fitts''s law: the time it takes to move to a target depends on how far away it is and how big it is. Large, close targets are fastest. Interface designers lean on this constantly. On a computer, the edges and corners of the screen stop the pointer, which in effect makes targets placed there very large — and very quick to reach.', 'design', null, 'Wikipedia: Fitts''s law', 'https://en.wikipedia.org/wiki/Fitts%27s_law', '{"quiz": {"question": "According to Fitts''s law, which target is quickest to reach?", "options": ["A small, nearby one", "A large, nearby one", "A large, distant one"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-006', 'The paths people actually take', 'A desire path is the worn track that appears where people repeatedly walk across grass rather than follow the paved route. It usually marks the shortest or easiest way between two points. Some planners treat these tracks as a nuisance; others treat them as free research, waiting to see where paths appear before deciding where to lay paving. Either way, they are a record of what people actually do.', 'design', null, 'Wikipedia: Desire path', 'https://en.wikipedia.org/wiki/Desire_path', '{"quiz": null, "prompt": "Look for a desire path on your next walk. Where does it lead?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-007', 'A sign you can read from behind', 'The stop sign''s eight-sided shape was chosen in the United States in the early 1920s. An unusual outline has practical advantages: the sign can be recognised at night or when its face is obscured, and drivers approaching from the opposite direction can identify it from the back and know that others have to stop. The signs were not always red; yellow was common until a 1954 standard changed the colour.', 'design', null, 'Wikipedia: Stop sign', 'https://en.wikipedia.org/wiki/Stop_sign', '{"quiz": {"question": "What colour were many early stop signs?", "options": ["Yellow", "Blue", "Green"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-008', 'Designs that remember their past', 'A skeuomorph is a feature carried over from an older version of an object, where it was necessary, into a newer one, where it is only decoration. Rivets printed on jeans pockets, a camera shutter sound on a phone, and a notes app styled like yellow lined paper are all examples. Such cues can make something new feel familiar, which is why early touchscreen software used so many of them.', 'design', null, 'Wikipedia: Skeuomorph', 'https://en.wikipedia.org/wiki/Skeuomorph', '{"quiz": null, "prompt": "Find one skeuomorph within arm''s reach.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-009', 'A common language for colour', 'In 1963 Lawrence Herbert introduced the Pantone Matching System, a book of standardised, numbered colours. Before it, a designer and a printer could easily disagree about what "the same red" meant. With a shared reference, a colour could be specified by number and reproduced by different printers in different places. The system is still used to keep brand colours consistent across packaging, print and products.', 'design', null, 'Wikipedia: Pantone', 'https://en.wikipedia.org/wiki/Pantone', '{"quiz": {"question": "What problem did Pantone''s system solve?", "options": ["Mixing paint cheaply", "Matching colours between printers", "Naming new colours"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-010', 'Pictures instead of words', 'In 1920s Vienna the social scientist Otto Neurath, working with Marie Reidemeister and the artist Gerd Arntz, developed Isotype, a method of showing statistics with rows of simple repeated pictograms. A larger quantity was shown by more symbols rather than by a bigger symbol, so that amounts could be compared at a glance. Its clean figures are an ancestor of the pictograms used on signs in airports and stations today.', 'design', null, 'Wikipedia: Isotype (picture language)', 'https://en.wikipedia.org/wiki/Isotype_(picture_language)', '{"quiz": {"question": "How did Isotype show a larger quantity?", "options": ["More symbols", "A darker symbol", "A bigger symbol"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-011', 'The Olympic figures on a grid', 'For the 1972 Olympic Games in Munich, the German designer Otl Aicher led a team that created a complete visual identity, including a set of pictograms for each sport. The figures were built on a strict grid of horizontal, vertical and diagonal lines, which made them consistent and easy to read without any language. They became one of the most influential pictogram systems ever made.', 'design', null, 'Wikipedia: Otl Aicher', 'https://en.wikipedia.org/wiki/Otl_Aicher', '{"quiz": null, "prompt": "Spot a pictogram today. Could you understand it with no words at all?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-012', 'A logo sketched in a taxi', 'The I ♥ NY logo was created by the graphic designer Milton Glaser in the mid-1970s for a campaign to promote tourism in New York State. He is said to have sketched the idea in the back of a taxi, and he did the work without a fee, expecting the campaign to run for only a few months. It became one of the most imitated designs in the world.', 'design', null, 'Wikipedia: I Love New York', 'https://en.wikipedia.org/wiki/I_Love_New_York', '{"quiz": {"question": "Who designed the I ♥ NY logo?", "options": ["Paul Rand", "Milton Glaser", "Saul Bass"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-013', 'Doors that need instructions', 'In The Design of Everyday Things, first published in 1988, Don Norman argued that when people struggle to use an object, the fault usually lies with the design and not with them. A door that needs a "push" sign has failed to show how it works. Such doors are now nicknamed Norman doors. A flat plate suggests pushing; a handle suggests pulling. Good design makes the right action the obvious one.', 'design', null, 'Wikipedia: The Design of Everyday Things', 'https://en.wikipedia.org/wiki/The_Design_of_Everyday_Things', '{"quiz": null, "prompt": "Notice the next door that confuses you. What would fix it?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-014', 'Why A4 folds so neatly', 'The A series of paper sizes is built on one ratio: the long side is the short side multiplied by the square root of two. That is the only proportion where cutting a sheet in half across its length gives two sheets with the same shape as the original. The largest size, A0, has an area of one square metre. Halve it four times and you arrive at A4.', 'design', null, 'Wikipedia: ISO 216', 'https://en.wikipedia.org/wiki/ISO_216', '{"quiz": {"question": "What is the area of a sheet of A0?", "options": ["Half a square metre", "One square metre", "Two square metres"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-015', 'The typeface made for a cartoon dog', 'Comic Sans was designed by Vincent Connare at Microsoft in 1994. He had seen a test version of a friendly software guide in which a cartoon dog spoke in speech bubbles set in Times New Roman, and thought the formal typeface looked wrong. He drew a casual alternative based on the lettering in comic books. It was finished too late for that program but shipped with Windows soon afterwards.', 'design', null, 'Wikipedia: Comic Sans', 'https://en.wikipedia.org/wiki/Comic_Sans', '{"quiz": {"question": "What inspired the letterforms of Comic Sans?", "options": ["Children''s handwriting", "Chalkboard menus", "Comic book lettering"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-016', 'Three lines from 1981', 'The three stacked lines known as the hamburger icon were drawn by the designer Norm Cox for the Xerox Star, a pioneering office computer released in 1981. It marked a menu and was meant to resemble a small list. The symbol then largely vanished for decades before returning on smartphone screens, where space is tight and a tiny, recognisable menu button became valuable again.', 'design', null, 'Wikipedia: Hamburger button', 'https://en.wikipedia.org/wiki/Hamburger_button', '{"quiz": {"question": "Which computer first used the hamburger icon?", "options": ["Commodore 64", "Xerox Star", "Apple Lisa"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-017', 'The space between two letters', 'Kerning is the adjustment of space between particular pairs of letters so that text looks evenly spaced. Some pairs, such as A and V, leave an awkward gap if each letter simply sits in its own box, so type designers build in corrections for them. Good kerning is invisible. Bad kerning can make one word read as two, which is why designers adjust large headlines by eye.', 'design', null, 'Wikipedia: Kerning', 'https://en.wikipedia.org/wiki/Kerning', '{"quiz": null, "prompt": "Look at a shop sign or headline. Are any two letters too far apart?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-018', 'A lamp balanced on springs', 'The Anglepoise lamp was designed in 1932 by George Carwardine, an English engineer who specialised in vehicle suspension. He had developed a spring mechanism that could hold a jointed arm in any position without clamps, working rather like the tension of muscles in a human arm, and went looking for a use for it. A desk lamp that stays exactly where it is put turned out to be the answer.', 'design', null, 'Wikipedia: Anglepoise lamp', 'https://en.wikipedia.org/wiki/Anglepoise_lamp', '{"quiz": {"question": "What was the designer''s specialism?", "options": ["Aircraft wings", "Watchmaking", "Vehicle suspension"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-019', 'A student drew the recycling symbol', 'The three chasing arrows of the recycling symbol were designed in 1970 by Gary Anderson, then a 23-year-old student, for a competition run by a packaging company around the time of the first Earth Day. His design is based on the Möbius strip, a loop with a single continuous side. The symbol was placed in the public domain, which is why it appears freely on products everywhere.', 'design', null, 'Wikipedia: Recycling symbol', 'https://en.wikipedia.org/wiki/Recycling_symbol', '{"quiz": {"question": "Which shape is the recycling symbol based on?", "options": ["A Möbius strip", "A spiral", "A triangle knot"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-020', 'A chair meant to feel like a baseball glove', 'Charles and Ray Eames released their lounge chair and ottoman in 1956. Made of moulded plywood shells and leather cushions, it was a departure for designers known for affordable, mass-produced furniture. Charles Eames said he wanted it to have the warm, receptive look of a well-used first baseman''s mitt. The chair has been in continuous production ever since and is held in the collection of the Museum of Modern Art.', 'design', null, 'Wikipedia: Eames Lounge Chair', 'https://en.wikipedia.org/wiki/Eames_Lounge_Chair', '{"quiz": {"question": "What did Charles Eames compare the chair''s look to?", "options": ["An armchair in a club", "A sailing boat", "A baseball mitt"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('design-021', 'Grouping without boxes', 'In the early twentieth century a group of German psychologists described how people naturally organise what they see. Their Gestalt principles are still taught to designers. Things placed close together are seen as a group, which is the principle of proximity. Things that look alike are seen as related, which is similarity. A designer can therefore show that items belong together using only space and likeness, without drawing a single border.', 'design', null, 'Wikipedia: Principles of grouping', 'https://en.wikipedia.org/wiki/Principles_of_grouping', '{"quiz": null, "prompt": "Open any app. What tells you which items belong together — lines, or just space?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-001', 'A monster born from a rainy summer', 'In the cold, wet summer of 1816, a group of writers staying near Lake Geneva passed the time by challenging each other to write a ghost story. One of them was Mary Godwin, soon to be Mary Shelley, who was eighteen. Her idea grew into Frankenstein; or, The Modern Prometheus, published anonymously in 1818. It is often described as one of the first works of science fiction.', 'books', 'fiction', 'Wikipedia: Frankenstein', 'https://en.wikipedia.org/wiki/Frankenstein', '{"quiz": {"question": "How did Frankenstein begin?", "options": ["A stage play", "A newspaper serial", "A ghost-story challenge"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-002', 'The knight who read too much', 'Don Quixote, by Miguel de Cervantes, was published in two parts, in 1605 and 1615. Its hero is a gentleman who reads so many tales of chivalry that he decides to become a knight himself, riding out with a farmer, Sancho Panza, as his squire. It is frequently called the first modern novel, and it gave English the word quixotic for ideals that are noble and impractical.', 'books', 'fiction', 'Wikipedia: Don Quixote', 'https://en.wikipedia.org/wiki/Don_Quixote', '{"quiz": {"question": "Who is Don Quixote''s squire?", "options": ["Sancho Panza", "Dulcinea", "Rocinante"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-003', 'A novel a thousand years old', 'The Tale of Genji was written in the early eleventh century by Murasaki Shikibu, a lady-in-waiting at the Japanese imperial court. Across fifty-four chapters it follows the life and loves of a prince and the generation after him, with close attention to its characters'' inner feelings. It is often described as the world''s first novel, and it is still read, studied and adapted in Japan today.', 'books', 'fiction', 'Wikipedia: The Tale of Genji', 'https://en.wikipedia.org/wiki/The_Tale_of_Genji', '{"quiz": {"question": "Who wrote The Tale of Genji?", "options": ["Murasaki Shikibu", "Sei Shōnagon", "Matsuo Bashō"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-004', 'A first line written on an exam paper', 'J. R. R. Tolkien was a professor at Oxford, marking examination papers one summer, when he came across a page a student had left blank. On it he wrote: "In a hole in the ground there lived a hobbit." He did not yet know what a hobbit was. The story that grew from that sentence was published as The Hobbit in 1937.', 'books', 'fiction', 'Wikipedia: The Hobbit', 'https://en.wikipedia.org/wiki/The_Hobbit', '{"quiz": null, "prompt": "Write one opening sentence today, with no idea what comes next.", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-005', 'A classic written with fifty words', 'Green Eggs and Ham, published in 1960, uses just fifty different words. Its author, Theodor Geisel — Dr. Seuss — wrote it after his publisher, Bennett Cerf, bet him that he could not write a book with so small a vocabulary. His earlier book The Cat in the Hat had used 236. The restriction did the story no harm: it became one of the best-selling children''s books in English.', 'books', 'fiction', 'Wikipedia: Green Eggs and Ham', 'https://en.wikipedia.org/wiki/Green_Eggs_and_Ham', '{"quiz": {"question": "How many different words are in Green Eggs and Ham?", "options": ["50", "150", "236"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-006', 'A book to try: The Remains of the Day', 'Kazuo Ishiguro''s 1989 novel is narrated by Stevens, an English butler taking a rare motoring holiday in the 1950s. As he drives, he looks back over decades of loyal service and what it may have cost him. Very little is said outright; the story lives in what Stevens cannot quite admit. The novel won the Booker Prize, and Ishiguro was awarded the Nobel Prize in Literature in 2017.', 'books', 'fiction', 'Wikipedia: The Remains of the Day', 'https://en.wikipedia.org/wiki/The_Remains_of_the_Day', '{"quiz": null, "prompt": "If it sounds like your kind of book, add it to your list.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-007', 'The line Holmes never said', '"Elementary, my dear Watson" is perhaps the most famous thing Sherlock Holmes says. Yet the phrase does not appear in any of the sixty Holmes stories written by Arthur Conan Doyle. Holmes does say "Elementary" and he does say "my dear Watson", but never together. The combined line became attached to the character later, through stage and screen versions.', 'books', 'fiction', 'Wikipedia: Sherlock Holmes', 'https://en.wikipedia.org/wiki/Sherlock_Holmes', '{"quiz": {"question": "How many Holmes stories did Conan Doyle write?", "options": ["24", "112", "60"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-008', 'By the author of Sense and Sensibility', 'Pride and Prejudice appeared in 1813 without Jane Austen''s name on it. The title page said only that it was by the author of Sense and Sensibility — a book that had itself been credited simply to "A Lady". Austen had drafted an early version in the 1790s under the title First Impressions. None of her novels carried her name during her lifetime.', 'books', 'fiction', 'Wikipedia: Pride and Prejudice', 'https://en.wikipedia.org/wiki/Pride_and_Prejudice', '{"quiz": {"question": "What was the novel''s early working title?", "options": ["Pemberley", "Elizabeth", "First Impressions"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-009', 'A village where it rains for years', 'One Hundred Years of Solitude, by the Colombian writer Gabriel García Márquez, was published in 1967. It follows seven generations of the Buendía family in the invented town of Macondo, where extraordinary events are told in the same calm voice as ordinary ones. The novel is a landmark of the style known as magic realism. García Márquez received the Nobel Prize in Literature in 1982.', 'books', 'fiction', 'Wikipedia: One Hundred Years of Solitude', 'https://en.wikipedia.org/wiki/One_Hundred_Years_of_Solitude', '{"quiz": {"question": "What is the name of the novel''s town?", "options": ["Macondo", "Comala", "Santa Teresa"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-010', 'A library containing every book', 'In 1941 the Argentine writer Jorge Luis Borges published a short story called The Library of Babel. It imagines a universe made of hexagonal rooms lined with books that contain every possible combination of letters. Somewhere on its shelves is every book that could ever be written — and an overwhelming amount of nonsense. Its librarians spend their lives searching. The story runs to only a few pages.', 'books', 'fiction', 'Wikipedia: The Library of Babel', 'https://en.wikipedia.org/wiki/The_Library_of_Babel', '{"quiz": null, "prompt": "Short stories fit into small gaps. Could you read one this week?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-011', 'A book to try: The Making of Prince of Persia', 'In the 1980s Jordan Mechner, just out of university, kept a journal while he designed and programmed the game Prince of Persia. He later published those journals, covering 1985 to 1993. They record the doubts, false starts and small breakthroughs of making something new, including filming his younger brother running and jumping so that he could trace the footage into the game''s lifelike animation.', 'books', 'nonfiction', 'Wikipedia: Prince of Persia (1989 video game)', 'https://en.wikipedia.org/wiki/Prince_of_Persia_(1989_video_game)', '{"quiz": null, "prompt": "Would a creator''s diary interest you? Add it to your list.", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-012', 'About 180 copies changed everything', 'In the 1450s, in the German city of Mainz, Johannes Gutenberg completed a Bible printed with movable metal type. Around 180 copies are thought to have been made, some on paper and some on vellum. It was the first major book produced in Europe by this method, and it showed that books could be made in quantity. Forty-nine copies, complete or partial, are known to survive.', 'books', 'nonfiction', 'Wikipedia: Gutenberg Bible', 'https://en.wikipedia.org/wiki/Gutenberg_Bible', '{"quiz": {"question": "In which city was the Gutenberg Bible printed?", "options": ["Venice", "Paris", "Mainz"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-013', 'The dictionary that took generations', 'Work on what became the Oxford English Dictionary began in the 1850s, and its first edition was not completed until 1928. It was built from millions of quotation slips posted in by volunteer readers. One of the most prolific contributors, William Chester Minor, was a retired American army surgeon who sent his slips from Broadmoor, a secure psychiatric hospital where he was a patient.', 'books', 'nonfiction', 'Wikipedia: Oxford English Dictionary', 'https://en.wikipedia.org/wiki/Oxford_English_Dictionary', '{"quiz": {"question": "How was the dictionary''s evidence gathered?", "options": ["Slips from volunteer readers", "Royal archives", "Interviews"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-014', 'Good books for the price of cigarettes', 'In 1935 the publisher Allen Lane launched Penguin Books with ten paperback reprints priced at sixpence each. The story goes that he had found nothing worth reading at a railway station bookstall. Paperbacks existed already, but they were mostly of low quality. Penguin''s idea was that good writing, cleanly designed, could be sold cheaply and in places other than bookshops. It sold millions within a year.', 'books', 'nonfiction', 'Wikipedia: Penguin Books', 'https://en.wikipedia.org/wiki/Penguin_Books', '{"quiz": {"question": "How much did the first Penguins cost?", "options": ["Sixpence", "Half a crown", "One shilling"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-015', 'A book to try: Silent Spring', 'Rachel Carson was a marine biologist and a gifted writer. Her 1962 book Silent Spring described how synthetic pesticides, used widely and with little caution, were moving through the natural world and harming birds, fish and other wildlife. It was attacked by chemical companies and read by millions. The book is widely credited with helping to start the modern environmental movement.', 'books', 'nonfiction', 'Wikipedia: Silent Spring', 'https://en.wikipedia.org/wiki/Silent_Spring', '{"quiz": {"question": "What was Rachel Carson''s profession?", "options": ["Marine biologist", "Journalist", "Chemist"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-016', 'A diary in shorthand', 'Samuel Pepys, a naval administrator in London, kept a private diary from 1660 to 1669. He wrote it in shorthand, and it was not deciphered and published until the nineteenth century. It is one of the best eyewitness accounts of its age, covering the plague of 1665 and the Great Fire of 1666 — during which Pepys buried his wine and a Parmesan cheese in the garden to keep them safe.', 'books', 'nonfiction', 'Wikipedia: Samuel Pepys', 'https://en.wikipedia.org/wiki/Samuel_Pepys', '{"quiz": {"question": "What did Pepys bury during the Great Fire?", "options": ["His diary", "Gold coins", "Wine and cheese"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-017', 'The numbers on the spine', 'In 1876 the American librarian Melvil Dewey published a system that divides knowledge into ten main classes, each given a range of numbers, with decimals for ever finer subjects. Because a book''s number describes its subject and not its position on a particular shelf, a library can grow without renumbering anything. The Dewey Decimal Classification is still used by libraries in many countries.', 'books', 'nonfiction', 'Wikipedia: Dewey Decimal Classification', 'https://en.wikipedia.org/wiki/Dewey_Decimal_Classification', '{"quiz": null, "prompt": "Next time you''re in a library, find where your favourite subject lives.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-018', 'A birthday present became a record', 'Anne Frank was given a red-and-white checked autograph book for her thirteenth birthday in June 1942, and began using it as a diary. Weeks later her family went into hiding in Amsterdam, and she kept writing for just over two years. Her father, Otto, the only member of the family to survive, arranged for the diary to be published in 1947. It has since been translated into dozens of languages.', 'books', 'nonfiction', 'Wikipedia: The Diary of a Young Girl', 'https://en.wikipedia.org/wiki/The_Diary_of_a_Young_Girl', '{"quiz": {"question": "When was the diary first published?", "options": ["1947", "1942", "1960"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-019', 'The man who invented the essay', 'In 1580 the French writer Michel de Montaigne published a collection of short prose pieces on subjects from friendship to thumbs. He called them Essais — attempts, or trials — because each was a try at thinking something through, with himself as the test case. The form and its name both stuck. Whenever someone writes a personal, exploratory piece of prose, they are following Montaigne.', 'books', 'nonfiction', 'Wikipedia: Essays (Montaigne)', 'https://en.wikipedia.org/wiki/Essays_(Montaigne)', '{"quiz": {"question": "What does the French word \"essai\" mean?", "options": ["A letter", "An attempt", "A lesson"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('books-020', 'A book to try: A Short History of Nearly Everything', 'Bill Bryson is best known as a travel writer. In 2003 he published a book born of his own curiosity about how scientists know what they know: the age of the universe, the weight of the Earth, what is inside an atom. He tells the story through the often eccentric people who worked these things out. It won the Aventis Prize for general science books in 2004.', 'books', 'nonfiction', 'Wikipedia: A Short History of Nearly Everything', 'https://en.wikipedia.org/wiki/A_Short_History_of_Nearly_Everything', '{"quiz": null, "prompt": "Curious about how we know what we know? Add it to your list.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-001', 'Why the sky is blue', 'Sunlight looks white but is a mixture of every colour. As it passes through the air, it is scattered in all directions by the gas molecules it meets, and shorter wavelengths are scattered far more strongly than longer ones. Blue light therefore reaches your eyes from every part of the sky. At sunset the light travels through much more air, most of the blue is scattered away, and what remains looks orange and red.', 'science', null, 'Wikipedia: Rayleigh scattering', 'https://en.wikipedia.org/wiki/Rayleigh_scattering', '{"quiz": {"question": "Which light is scattered most by air?", "options": ["Longer, redder wavelengths", "Shorter, bluer wavelengths", "All equally"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-002', 'Why onions make you cry', 'Cutting an onion breaks open its cells and lets enzymes mix with sulphur compounds that were stored separately. A quick chain of reactions produces a gas called syn-propanethial-S-oxide. When the gas drifts up and reaches your eyes, it stimulates nerves there, and your tear glands respond by trying to wash the irritant away. Chilling the onion first, or using a sharper knife that crushes fewer cells, reduces the effect.', 'science', null, 'Wikipedia: Onion', 'https://en.wikipedia.org/wiki/Onion', '{"quiz": {"question": "What triggers the tears?", "options": ["A gas released by cut cells", "The smell alone", "Onion juice splashing"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-003', 'Bananas are very slightly radioactive', 'Bananas are rich in potassium, and a tiny fraction of all natural potassium is the radioactive form potassium-40. So a banana gives off a minute amount of radiation — as do potatoes, beans, nuts and your own body. The dose is far too small to matter, and the body keeps its potassium level steady however many bananas you eat. Scientists sometimes use the "banana equivalent dose" as an informal way to put small exposures in perspective.', 'science', null, 'Wikipedia: Banana equivalent dose', 'https://en.wikipedia.org/wiki/Banana_equivalent_dose', '{"quiz": {"question": "Which element makes bananas slightly radioactive?", "options": ["Calcium", "Iron", "Potassium"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-004', 'Counting the distance to lightning', 'Light from a lightning flash reaches you almost instantly, but its sound travels at roughly 343 metres per second in air. That gap is why thunder arrives late. Count the seconds between the flash and the rumble and divide by three: the answer is roughly the distance in kilometres. If the gap is getting shorter with each flash, the storm is moving towards you.', 'science', null, 'Wikipedia: Thunder', 'https://en.wikipedia.org/wiki/Thunder', '{"quiz": {"question": "A six-second gap means the lightning was about…", "options": ["2 km away", "6 km away", "600 m away"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-005', 'Why ice floats', 'Most substances shrink and become denser when they freeze. Water does the opposite. As it freezes, its molecules lock into an open, hexagonal arrangement that takes up about nine per cent more space than the liquid did. Ice is therefore less dense than water and floats on it. That oddity matters: lakes freeze from the top down, and the layer of ice insulates the liquid water — and the life — below.', 'science', null, 'Wikipedia: Ice', 'https://en.wikipedia.org/wiki/Ice', '{"quiz": {"question": "About how much does water expand when it freezes?", "options": ["9%", "1%", "25%"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-006', 'Eight-minute-old sunlight', 'Light travels at exactly 299,792,458 metres per second in a vacuum. The figure is exact because, since 1983, the metre has been defined by it. Even at that speed, light takes about eight minutes and twenty seconds to cross the 150 million kilometres from the Sun to the Earth. When you look at the Sun''s light on a wall, you are seeing light that left its surface before you started reading this card — probably.', 'science', null, 'Wikipedia: Speed of light', 'https://en.wikipedia.org/wiki/Speed_of_light', '{"quiz": {"question": "Roughly how long does sunlight take to reach Earth?", "options": ["8 hours", "8 minutes", "8 seconds"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-007', 'The photograph behind the double helix', 'In 1953 James Watson and Francis Crick proposed that DNA has the shape of a double helix, two strands twisted round each other. Their model drew on X-ray images made at King''s College London, in particular an image known as Photo 51, taken in 1952 by Raymond Gosling working under Rosalind Franklin. The picture''s X-shaped pattern was strong evidence for a helix. Franklin died in 1958, four years before the Nobel Prize for the discovery was awarded.', 'science', null, 'Wikipedia: Photo 51', 'https://en.wikipedia.org/wiki/Photo_51', '{"quiz": {"question": "What technique produced Photo 51?", "options": ["Radio imaging", "Electron microscopy", "X-ray diffraction"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-008', 'A discovery left on a windowsill', 'In 1928 the Scottish scientist Alexander Fleming returned from a holiday to his laboratory in London and found that a mould had contaminated one of his dishes of bacteria. Around the mould, the bacteria had been killed. He identified the mould as Penicillium and named its active substance penicillin. Turning it into a usable medicine took another decade and the work of other scientists, notably Howard Florey and Ernst Chain.', 'science', null, 'Wikipedia: Penicillin', 'https://en.wikipedia.org/wiki/Penicillin', '{"quiz": {"question": "What contaminated Fleming''s dish?", "options": ["A mould", "A virus", "Dust"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-009', 'The coldest anything can be', 'Temperature is a measure of how much the particles in a substance are moving. Cool something and they slow down. Absolute zero is the limit at which they would have the least motion that the laws of physics allow: zero kelvin, or minus 273.15 degrees Celsius. Nothing can be cooled all the way there, though laboratories have reached within a tiny fraction of a degree of it.', 'science', null, 'Wikipedia: Absolute zero', 'https://en.wikipedia.org/wiki/Absolute_zero', '{"quiz": {"question": "What is absolute zero in Celsius?", "options": ["−100 °C", "−273.15 °C", "−459.67 °C"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-010', 'Two tides a day', 'The Moon''s gravity pulls more strongly on the side of the Earth nearest to it than on the far side. That difference stretches the oceans slightly into two bulges, one facing the Moon and one facing away. As the Earth rotates, most coasts pass through both bulges, giving two high tides a day. When the Sun and Moon line up, at new and full moon, their effects add together into extra-high spring tides.', 'science', null, 'Wikipedia: Tide', 'https://en.wikipedia.org/wiki/Tide', '{"quiz": {"question": "When do the strongest (spring) tides occur?", "options": ["Only in spring", "At new and full moon", "At half moon"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-011', 'The Moon keeps one face towards us', 'The Moon takes the same time to spin once on its axis as it takes to orbit the Earth, a little over 27 days. As a result, the same side always faces us. This is not a coincidence. Over a very long time, the Earth''s gravity slowed the Moon''s rotation until the two periods matched, an arrangement called tidal locking. The far side was not seen until a Soviet probe photographed it in 1959.', 'science', null, 'Wikipedia: Tidal locking', 'https://en.wikipedia.org/wiki/Tidal_locking', '{"quiz": {"question": "When was the Moon''s far side first photographed?", "options": ["1935", "1969", "1959"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-012', 'A table with gaps left on purpose', 'In 1869 the Russian chemist Dmitri Mendeleev arranged the known elements by atomic weight and noticed that their properties repeated in a regular pattern. Where no known element fitted, he left a gap, and he predicted the properties of the elements that should fill them. Gallium, discovered in 1875, and germanium, discovered in 1886, matched his predictions closely — strong evidence that his periodic table reflected something real.', 'science', null, 'Wikipedia: Dmitri Mendeleev', 'https://en.wikipedia.org/wiki/Dmitri_Mendeleev', '{"quiz": {"question": "What did Mendeleev do where no element fitted?", "options": ["Invented a name", "Rearranged the table", "Left a gap and predicted one"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-013', 'Why a siren changes pitch', 'As an ambulance approaches, each sound wave from its siren is emitted from a little closer to you than the last, so the waves arrive bunched together and the pitch sounds higher. As it moves away, the waves are stretched out and the pitch drops. This is the Doppler effect, described by the Austrian physicist Christian Doppler in 1842. Astronomers use the same effect in light to measure how fast stars and galaxies are moving.', 'science', null, 'Wikipedia: Doppler effect', 'https://en.wikipedia.org/wiki/Doppler_effect', '{"quiz": null, "prompt": "Listen for it the next time a vehicle with a siren passes you.", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-014', 'Nobody else sees your rainbow', 'A rainbow forms when sunlight enters raindrops, bends, reflects off the inside of each drop, and bends again on the way out, spreading into colours. The light returns at an angle of about 42 degrees from the direction opposite the Sun. Because that angle is measured from your own eyes, the rainbow you see is made by a particular set of drops. Someone standing beside you sees a slightly different one.', 'science', null, 'Wikipedia: Rainbow', 'https://en.wikipedia.org/wiki/Rainbow', '{"quiz": {"question": "Where is the Sun when you see a rainbow?", "options": ["Directly overhead", "Behind you", "In front of you"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-015', 'The smell of rain has a name', 'The earthy scent that rises when rain falls on dry ground is called petrichor. The word was coined in 1964 by two Australian researchers, Isabel Bear and Richard Thomas. Part of the smell comes from oils released by plants during dry spells, and part from geosmin, a compound made by soil bacteria. Human noses are remarkably sensitive to geosmin and can detect it at extremely low concentrations.', 'science', null, 'Wikipedia: Petrichor', 'https://en.wikipedia.org/wiki/Petrichor', '{"quiz": {"question": "Which organisms produce geosmin?", "options": ["Tree roots", "Earthworms", "Soil bacteria"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-016', 'Why some years have an extra day', 'The Earth takes about 365.2422 days to go round the Sun, not a neat 365. Adding a leap day every four years overcorrects slightly, so the Gregorian calendar has a refinement: century years are leap years only if they can be divided by 400. That is why 2000 was a leap year but 1900 was not, and 2100 will not be. The year 2027 is an ordinary one, with 365 days.', 'science', null, 'Wikipedia: Leap year', 'https://en.wikipedia.org/wiki/Leap_year', '{"quiz": {"question": "Which of these was NOT a leap year?", "options": ["2000", "2024", "1900"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-017', 'Where Celsius and Fahrenheit agree', 'The Celsius and Fahrenheit scales use different zero points and different sizes of degree, so they almost never show the same number. There is exactly one exception. At minus forty, the two scales cross: minus 40 degrees Celsius is the same temperature as minus 40 degrees Fahrenheit. You can check it with the conversion: multiply by nine fifths, then add thirty-two.', 'science', null, 'Wikipedia: Fahrenheit', 'https://en.wikipedia.org/wiki/Fahrenheit', '{"quiz": {"question": "At what temperature do the two scales match?", "options": ["−40", "−273", "0"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-018', 'Space is silent', 'Sound is a vibration passed along from particle to particle, through air, water or a solid. In the near-vacuum of space there are far too few particles to carry it, so there is nothing to hear. Astronauts on spacewalks talk by radio, which uses electromagnetic waves and needs no medium at all. The roaring spaceships of the cinema are an artistic choice.', 'science', null, 'Wikipedia: Sound', 'https://en.wikipedia.org/wiki/Sound', '{"quiz": {"question": "How do astronauts talk during spacewalks?", "options": ["By radio", "By sign language only", "By shouting"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-019', 'You are mostly not the same cells', 'An adult human body is made of tens of trillions of cells; careful estimates put the figure at roughly thirty to forty trillion. They do not all last a lifetime. Cells lining the gut are replaced within days, red blood cells circulate for about four months, and skin is continually shed and renewed. Others, such as most of the neurons in the brain, are with you for life.', 'science', null, 'Wikipedia: Cell (biology)', 'https://en.wikipedia.org/wiki/Cell_(biology)', '{"quiz": {"question": "About how long does a red blood cell last?", "options": ["Four days", "Four years", "Four months"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('science-020', 'A number that never ends', 'Pi is the ratio of a circle''s circumference to its diameter, a little more than 3.14159. It is an irrational number: its decimal digits go on for ever without settling into a repeating pattern. Archimedes trapped its value between two fractions more than two thousand years ago by drawing polygons inside and outside a circle. Computers have now calculated trillions of digits, far more than any practical task needs.', 'science', null, 'Wikipedia: Pi', 'https://en.wikipedia.org/wiki/Pi', '{"quiz": null, "prompt": "Measure around a mug and across it. Divide one by the other. How close did you get?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-001', 'Cleopatra and the pyramids', 'The Great Pyramid of Giza was completed around 2560 BC. Cleopatra, the last active ruler of Ptolemaic Egypt, was born in 69 BC — about two and a half thousand years later. The first Moon landing came in 1969, roughly two thousand years after her death. Cleopatra therefore lived closer in time to the Moon landing than to the building of the Great Pyramid. Ancient Egypt lasted a very long time.', 'history', null, 'Wikipedia: Great Pyramid of Giza', 'https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza', '{"quiz": {"question": "Cleopatra lived closer in time to…", "options": ["Neither; they''re equal", "The building of the Great Pyramid", "The Moon landing"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-002', 'A university older than an empire', 'There is evidence of teaching at Oxford as early as 1096, which makes it the oldest university in the English-speaking world. The Aztec capital, Tenochtitlan, is traditionally dated to 1325, and the alliance usually called the Aztec Empire formed about a century after that. Students had been attending lectures in Oxford for more than two hundred years before the city at the heart of that empire was founded.', 'history', null, 'Wikipedia: University of Oxford', 'https://en.wikipedia.org/wiki/University_of_Oxford', '{"quiz": {"question": "Which is older?", "options": ["They began together", "Teaching at Oxford", "Tenochtitlan"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-003', 'The fire that began in a bakery', 'The Great Fire of London broke out in the early hours of 2 September 1666 in Thomas Farriner''s bakery on Pudding Lane. Driven by a strong east wind through tightly packed timber buildings, it burned for four days. It destroyed more than thirteen thousand houses and the medieval St Paul''s Cathedral. The official death toll was remarkably small, though historians note that many deaths may simply not have been recorded.', 'history', null, 'Wikipedia: Great Fire of London', 'https://en.wikipedia.org/wiki/Great_Fire_of_London', '{"quiz": {"question": "Where did the Great Fire start?", "options": ["Drury Lane", "Pudding Lane", "Fleet Street"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-004', 'One stone, three scripts', 'The Rosetta Stone was found in 1799 by French soldiers in Egypt. It carries a decree from 196 BC written three times: in Egyptian hieroglyphs, in the everyday Demotic script, and in ancient Greek. Because scholars could read the Greek, the stone offered a way into the other two. In 1822 Jean-François Champollion announced that he had worked out how hieroglyphs functioned, opening up three thousand years of writing.', 'history', null, 'Wikipedia: Rosetta Stone', 'https://en.wikipedia.org/wiki/Rosetta_Stone', '{"quiz": {"question": "Which language on the stone could scholars already read?", "options": ["Latin", "Ancient Greek", "Hieroglyphs"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-005', 'The shortest war on record', 'On the morning of 27 August 1896, British warships opened fire on the palace of the Sultan of Zanzibar, after a new sultan took power without British approval and refused to step down. The bombardment began at about two minutes past nine. By around twenty to ten, the palace was in ruins and the flag had been shot down. The Anglo-Zanzibar War, lasting between 38 and 45 minutes, is generally considered the shortest in recorded history.', 'history', null, 'Wikipedia: Anglo-Zanzibar War', 'https://en.wikipedia.org/wiki/Anglo-Zanzibar_War', '{"quiz": {"question": "About how long did the war last?", "options": ["Under an hour", "One day", "One week"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-006', 'Eleven days that never happened', 'In 1752 Britain and its colonies switched from the Julian calendar to the Gregorian one, which much of Europe had adopted long before. To catch up, eleven days were dropped. People went to bed on Wednesday 2 September and woke up on Thursday 14 September. The same law also moved the start of the legal year from 25 March to 1 January.', 'history', null, 'Wikipedia: Calendar (New Style) Act 1750', 'https://en.wikipedia.org/wiki/Calendar_(New_Style)_Act_1750', '{"quiz": {"question": "What date followed 2 September 1752 in Britain?", "options": ["1 October", "3 September", "14 September"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-007', 'A town stopped in a day', 'In AD 79 Mount Vesuvius erupted and buried the Roman town of Pompeii under several metres of ash and pumice. The town lay largely forgotten for centuries until excavations began in 1748. Because it was sealed so suddenly, Pompeii preserves everyday Roman life in unusual detail: bakeries with loaves still in the oven, election slogans painted on walls, and graffiti scratched by ordinary people.', 'history', null, 'Wikipedia: Pompeii', 'https://en.wikipedia.org/wiki/Pompeii', '{"quiz": {"question": "When did excavations at Pompeii begin?", "options": ["1748", "1901", "1492"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-008', 'The road that had no name', 'For centuries, goods, ideas and religions moved along a web of trade routes linking China, Central Asia, India, Persia and the Mediterranean. Nobody travelling them called them the Silk Road. That name was coined in 1877 by the German geographer Ferdinand von Richthofen. Silk was only one of many things carried; paper, spices, glass, horses and diseases travelled the same routes.', 'history', null, 'Wikipedia: Silk Road', 'https://en.wikipedia.org/wiki/Silk_Road', '{"quiz": {"question": "When was the term \"Silk Road\" coined?", "options": ["200 BC", "1271", "1877"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-009', 'The army that lost to birds', 'In late 1932, farmers in Western Australia asked for help with some twenty thousand emus that were eating their wheat. The government sent soldiers with two machine guns. The birds proved fast, scattered widely and were hard to hit; after several weeks and thousands of rounds, the operation was withdrawn with the emu population largely intact. The episode became known, with some irony, as the Emu War.', 'history', null, 'Wikipedia: Emu War', 'https://en.wikipedia.org/wiki/Emu_War', '{"quiz": {"question": "In which country did the Emu War take place?", "options": ["New Zealand", "South Africa", "Australia"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-010', 'When tulips cost as much as houses', 'In the Dutch Republic of the 1630s, tulips were a fashionable luxury, and rare varieties with streaked petals were especially prized. Contracts to buy bulbs changed hands at ever higher prices until, in February 1637, the market abruptly collapsed. Tulip mania is often cited as the first recorded speculative bubble, though modern historians think its effect on the wider Dutch economy was much smaller than legend suggests.', 'history', null, 'Wikipedia: Tulip mania', 'https://en.wikipedia.org/wiki/Tulip_mania', '{"quiz": {"question": "In which year did the tulip market collapse?", "options": ["1720", "1929", "1637"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-011', 'A computer from a shipwreck', 'In 1901 sponge divers recovered a lump of corroded bronze from an ancient shipwreck off the Greek island of Antikythera. Inside were the remains of at least thirty interlocking gear wheels. The Antikythera mechanism, made around two thousand years ago, was a hand-cranked device for modelling the movements of the Sun and Moon and predicting eclipses. Nothing of comparable mechanical complexity is known from the following thousand years.', 'history', null, 'Wikipedia: Antikythera mechanism', 'https://en.wikipedia.org/wiki/Antikythera_mechanism', '{"quiz": {"question": "What was the mechanism used for?", "options": ["Grinding grain", "Modelling the heavens", "Telling the time at sea"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-012', 'Twelve seconds in the air', 'On 17 December 1903, near Kitty Hawk in North Carolina, Orville Wright flew a powered aeroplane for twelve seconds and covered 37 metres — less than the wingspan of many modern airliners. He and his brother Wilbur made four flights that day; the longest lasted 59 seconds. Just under sixty-six years later, people walked on the Moon.', 'history', null, 'Wikipedia: Wright Flyer', 'https://en.wikipedia.org/wiki/Wright_Flyer', '{"quiz": {"question": "How long did the first flight last?", "options": ["12 minutes", "2 minutes", "12 seconds"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-013', 'A city in the clouds', 'Machu Picchu stands on a mountain ridge in the Andes of Peru, about 2,400 metres above sea level. It was built in the fifteenth century, probably as an estate for the Inca emperor Pachacuti, and was abandoned around the time of the Spanish conquest. Its stone walls were fitted together without mortar. The site was little known outside the region until the American explorer Hiram Bingham publicised it in 1911.', 'history', null, 'Wikipedia: Machu Picchu', 'https://en.wikipedia.org/wiki/Machu_Picchu', '{"quiz": {"question": "Which civilisation built Machu Picchu?", "options": ["The Aztecs", "The Maya", "The Inca"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-014', 'Laws carved in stone', 'Around 1754 BC, Hammurabi, king of Babylon, had a set of 282 laws inscribed on a black stone pillar more than two metres tall. They cover trade, property, family and injury, each written as a case: if this happens, then that follows. It is one of the oldest long legal texts to survive. The stone was rediscovered in 1901 and now stands in the Louvre in Paris.', 'history', null, 'Wikipedia: Code of Hammurabi', 'https://en.wikipedia.org/wiki/Code_of_Hammurabi', '{"quiz": {"question": "Where is the stone kept today?", "options": ["The British Museum", "The Louvre", "Baghdad"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-015', 'Vikings in America, dated to the year', 'At L''Anse aux Meadows in Newfoundland, Canada, archaeologists in the 1960s uncovered the remains of a Norse settlement — proof that Europeans reached the Americas centuries before Columbus. In 2021 researchers dated wood cut there with metal tools by finding the trace of a known solar storm in its tree rings. Counting outward gave an exact felling year: 1021.', 'history', null, 'Wikipedia: L''Anse aux Meadows', 'https://en.wikipedia.org/wiki/L%27Anse_aux_Meadows', '{"quiz": {"question": "In which modern country is L''Anse aux Meadows?", "options": ["Canada", "Greenland", "United States"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-016', 'The first postage stamp', 'Before 1840, the person receiving a letter in Britain usually paid for it, and the cost depended on distance. A reform proposed by Rowland Hill replaced this with a low, uniform rate paid in advance by the sender. Proof of payment was a small adhesive label: the Penny Black, issued in May 1840 and bearing a profile of Queen Victoria. It was the world''s first adhesive postage stamp.', 'history', null, 'Wikipedia: Penny Black', 'https://en.wikipedia.org/wiki/Penny_Black', '{"quiz": {"question": "Who usually paid for a letter before 1840?", "options": ["The recipient", "The sender", "The parish"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-017', 'A wall that fell in one night', 'The Berlin Wall was built in August 1961 by East Germany to stop its citizens leaving for the West, and it divided the city for twenty-eight years. On the evening of 9 November 1989, after an East German spokesman mistakenly announced that new travel rules took effect immediately, crowds gathered at the checkpoints. Overwhelmed guards opened the gates, and people began crossing freely and climbing onto the wall.', 'history', null, 'Wikipedia: Berlin Wall', 'https://en.wikipedia.org/wiki/Berlin_Wall', '{"quiz": {"question": "In which year was the Berlin Wall built?", "options": ["1961", "1949", "1975"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-018', 'Rules for nothing', 'A symbol for an empty place in a number was used in several ancient cultures. Treating zero as a number in its own right was a further step. In AD 628 the Indian mathematician Brahmagupta wrote down rules for arithmetic with zero — for example, that a number minus itself is zero, and that a number multiplied by zero is zero. The idea travelled west through the Islamic world and reached Europe centuries later.', 'history', null, 'Wikipedia: 0', 'https://en.wikipedia.org/wiki/0', '{"quiz": {"question": "Who set out early rules for arithmetic with zero?", "options": ["Brahmagupta", "Fibonacci", "Euclid"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-019', 'Mammoths outlived the first pyramids', 'Woolly mammoths disappeared from the mainland of Eurasia and North America around ten thousand years ago. But a small population survived on Wrangel Island, in the Arctic Ocean off Siberia, until roughly four thousand years ago. By then the Great Pyramid of Giza had already been standing for centuries. The last mammoths and the pharaohs shared a planet.', 'history', null, 'Wikipedia: Woolly mammoth', 'https://en.wikipedia.org/wiki/Woolly_mammoth', '{"quiz": {"question": "Where did the last woolly mammoths live?", "options": ["Wrangel Island", "Iceland", "Alaska"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('history-020', 'A charter sealed in a meadow', 'In June 1215, at Runnymede beside the River Thames, King John of England agreed to a charter demanded by rebellious barons. Most of its clauses dealt with specific feudal grievances. But Magna Carta also set down the principle that the king was not above the law, and promised that no free man would be imprisoned except by lawful judgment. Four copies of the 1215 text survive.', 'history', null, 'Wikipedia: Magna Carta', 'https://en.wikipedia.org/wiki/Magna_Carta', '{"quiz": {"question": "How many copies of the 1215 Magna Carta survive?", "options": ["One", "Twelve", "Four"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-001', 'The theft that made the Mona Lisa famous', 'On 21 August 1911 the Mona Lisa was stolen from the Louvre by Vincenzo Peruggia, an Italian workman who had helped build its glass case. He hid in the museum and walked out with the painting under his coat. It was missing for more than two years, during which newspapers around the world printed its picture. The painting was recovered in Florence in 1913 — by then far more famous than before.', 'art', 'visual', 'Wikipedia: Mona Lisa', 'https://en.wikipedia.org/wiki/Mona_Lisa', '{"quiz": {"question": "How long was the Mona Lisa missing?", "options": ["Two weeks", "Twenty years", "Over two years"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-002', 'A night sky painted from memory', 'Vincent van Gogh painted The Starry Night in June 1889 while staying at an asylum in Saint-Rémy-de-Provence. The view is based on the one from his window just before sunrise, but he painted it during the day, from memory, and added the village. He considered the picture a failure. It is now one of the most recognised paintings in the world, and hangs in the Museum of Modern Art in New York.', 'art', 'visual', 'Wikipedia: The Starry Night', 'https://en.wikipedia.org/wiki/The_Starry_Night', '{"quiz": {"question": "Where does The Starry Night hang today?", "options": ["The Louvre, Paris", "MoMA, New York", "Van Gogh Museum, Amsterdam"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-003', 'The wave made with imported blue', 'The Great Wave off Kanagawa is a woodblock print by the Japanese artist Hokusai, published around 1831 as part of his series Thirty-six Views of Mount Fuji. The mountain sits small and calm beneath a towering wave. Hokusai was about seventy when he made it. The print''s deep colour comes from Prussian blue, a synthetic pigment then newly available in Japan.', 'art', 'visual', 'Wikipedia: The Great Wave off Kanagawa', 'https://en.wikipedia.org/wiki/The_Great_Wave_off_Kanagawa', '{"quiz": {"question": "What small shape sits beneath the wave?", "options": ["A temple", "Mount Fuji", "The moon"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-004', 'A movement named by an insult', 'In 1874 a group of painters who had been rejected by the official Paris Salon held their own exhibition. Among the works was Claude Monet''s hazy harbour scene Impression, Sunrise. The critic Louis Leroy seized on the title to mock the whole show as mere "impressions", unfinished sketches. The painters adopted the name. Impressionism became one of the most loved movements in the history of art.', 'art', 'visual', 'Wikipedia: Impression, Sunrise', 'https://en.wikipedia.org/wiki/Impression,_Sunrise', '{"quiz": {"question": "Whose painting gave Impressionism its name?", "options": ["Claude Monet", "Édouard Manet", "Edgar Degas"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-005', 'The painter of a few dozen pictures', 'Johannes Vermeer worked slowly in the Dutch city of Delft in the seventeenth century, and only around thirty-five paintings are generally attributed to him today. Most show quiet domestic rooms lit from a window on the left. Girl with a Pearl Earring, painted around 1665, is not a portrait of a known person but a tronie — a study of a face and expression. He was little known for two centuries after his death.', 'art', 'visual', 'Wikipedia: Johannes Vermeer', 'https://en.wikipedia.org/wiki/Johannes_Vermeer', '{"quiz": null, "prompt": "Notice how light from a window falls across a room today.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-006', 'The first night at the pictures', 'On 28 December 1895, in a basement room of the Grand Café in Paris, the brothers Auguste and Louis Lumière showed ten short films to a paying audience. Each lasted under a minute. The first showed workers leaving the Lumière factory. The programme is usually regarded as the birth of cinema as a shared public experience, although others had been experimenting with moving pictures too.', 'art', 'film', 'Wikipedia: Auguste and Louis Lumière', 'https://en.wikipedia.org/wiki/Auguste_and_Louis_Lumi%C3%A8re', '{"quiz": {"question": "In which city was the Lumières'' first paid screening?", "options": ["London", "Lyon", "Paris"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-007', '"You ain''t heard nothin'' yet"', 'The Jazz Singer, released in October 1927, was the first feature-length film with synchronised spoken dialogue. Most of it is still silent, with title cards, but in a few sequences the star, Al Jolson, sings and speaks, including the line "You ain''t heard nothin'' yet". Audiences were astonished. Within a few years, the silent film had all but disappeared from Hollywood.', 'art', 'film', 'Wikipedia: The Jazz Singer', 'https://en.wikipedia.org/wiki/The_Jazz_Singer', '{"quiz": {"question": "When was The Jazz Singer released?", "options": ["1939", "1927", "1915"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-008', 'A feature film drawn by hand', 'Snow White and the Seven Dwarfs, released by Walt Disney in 1937, was the first full-length animated feature made with traditional hand-painted cels. During its three years in production, many in Hollywood called it "Disney''s Folly", doubting that audiences would sit through a feature-length cartoon. It became a huge success and established the animated feature as a form.', 'art', 'film', 'Wikipedia: Snow White and the Seven Dwarfs (1937 film)', 'https://en.wikipedia.org/wiki/Snow_White_and_the_Seven_Dwarfs_(1937_film)', '{"quiz": {"question": "What was the film nicknamed during production?", "options": ["Disney''s Folly", "Walt''s Dream", "The Long Cartoon"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-009', 'The first feature made entirely by computer', 'Toy Story, released in November 1995, was the first feature-length film made entirely with computer animation. It was produced by Pixar and directed by John Lasseter. Toys were a practical subject: the technology of the time handled smooth plastic surfaces far better than skin, hair or cloth. Each frame could take hours to render, and the film contains well over a hundred thousand of them.', 'art', 'film', 'Wikipedia: Toy Story', 'https://en.wikipedia.org/wiki/Toy_Story', '{"quiz": {"question": "Why were toys a practical subject in 1995?", "options": ["Toys were cheap to license", "Children were the only audience", "Plastic was easier to render"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-010', 'The same face, three meanings', 'Around 1920 the Soviet film-maker Lev Kuleshov ran an editing experiment. He cut the same shot of an actor''s expressionless face together with a bowl of soup, a child in a coffin, and a woman on a sofa. Audiences are said to have praised the actor''s subtle hunger, grief and desire. The Kuleshov effect shows that viewers build meaning from the join between two shots, not just from each shot alone.', 'art', 'film', 'Wikipedia: Kuleshov effect', 'https://en.wikipedia.org/wiki/Kuleshov_effect', '{"quiz": null, "prompt": "In the next film you watch, notice a cut. What does the second shot make you assume?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-011', 'The composer who couldn''t hear the applause', 'Beethoven''s Ninth Symphony was first performed in Vienna on 7 May 1824. By then the composer was almost completely deaf. He stood on stage beating time, though the musicians had been told to follow another conductor. According to accounts of the evening, when the piece ended he was still facing the orchestra, and one of the soloists gently turned him round so that he could see the audience cheering.', 'art', 'music', 'Wikipedia: Symphony No. 9 (Beethoven)', 'https://en.wikipedia.org/wiki/Symphony_No._9_(Beethoven)', '{"quiz": {"question": "In which city did the Ninth Symphony premiere?", "options": ["Vienna", "Berlin", "Bonn"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-012', 'Four and a half minutes of nothing', 'In 1952 the pianist David Tudor sat at a piano in Woodstock, New York, and performed a new piece by John Cage. He played no notes. The work, titled 4′33″ after its length, consists of three movements in which the performer makes no deliberate sound. Cage''s point was that there is no such thing as silence: the piece is whatever the audience happens to hear in the room.', 'art', 'music', 'Wikipedia: 4′33″', 'https://en.wikipedia.org/wiki/4%E2%80%B233%E2%80%B3', '{"quiz": null, "prompt": "Sit still for one minute and list every sound you can hear.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-013', 'The first recorded words', 'In 1877 Thomas Edison built the phonograph, the first machine that could both record sound and play it back. It worked by scratching a groove into tinfoil wrapped round a cylinder. For his first test, Edison recited the nursery rhyme "Mary had a little lamb" — and was reportedly astonished when the machine spoke the words back to him.', 'art', 'music', 'Wikipedia: Phonograph', 'https://en.wikipedia.org/wiki/Phonograph', '{"quiz": {"question": "What did Edison recite in his first test?", "options": ["The alphabet", "Mary had a little lamb", "Twinkle, twinkle"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-014', 'A concert on a roof', 'On 30 January 1969 the Beatles carried their instruments up to the roof of their Apple headquarters in central London and played an unannounced lunchtime set. Office workers gathered in the street below and on neighbouring rooftops. After about forty minutes, the police asked them to turn the volume down, and the performance ended. It was the last time the band played live in public.', 'art', 'music', 'Wikipedia: The Beatles'' rooftop concert', 'https://en.wikipedia.org/wiki/The_Beatles%27_rooftop_concert', '{"quiz": {"question": "In which city was the rooftop concert?", "options": ["Hamburg", "Liverpool", "London"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-015', 'Bach, plugged in', 'In 1968 the composer Wendy Carlos released Switched-On Bach, an album of pieces by Johann Sebastian Bach performed entirely on a Moog synthesiser. The instrument could play only one note at a time, so every line had to be recorded separately and layered on tape. The album was a surprise hit, won three Grammy Awards, and convinced many listeners that the synthesiser was a serious musical instrument.', 'art', 'music', 'Wikipedia: Switched-On Bach', 'https://en.wikipedia.org/wiki/Switched-On_Bach', '{"quiz": {"question": "Which instrument was used for Switched-On Bach?", "options": ["Theremin", "Electric organ", "Moog synthesiser"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-016', 'A style named after a fair', 'Art Deco takes its name from an exhibition held in Paris in 1925, the International Exhibition of Modern Decorative and Industrial Arts. The style combined bold geometry, rich materials and a taste for speed and modernity. It shaped everything from jewellery and cinemas to ocean liners and skyscrapers, including the Chrysler Building in New York. The name itself only came into common use in the 1960s.', 'art', 'designhistory', 'Wikipedia: Art Deco', 'https://en.wikipedia.org/wiki/Art_Deco', '{"quiz": {"question": "Which city hosted the 1925 exhibition?", "options": ["Paris", "New York", "Milan"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-017', 'Useful or beautiful', 'William Morris was a Victorian designer, poet and campaigner who disliked the shoddy factory goods of his age. His firm made wallpaper, textiles and furniture using traditional craft methods, with dense patterns drawn from plants and birds. "Have nothing in your houses," he advised, "that you do not know to be useful, or believe to be beautiful." He was a leading figure in the Arts and Crafts movement.', 'art', 'designhistory', 'Wikipedia: William Morris', 'https://en.wikipedia.org/wiki/William_Morris', '{"quiz": null, "prompt": "Look around the room. What here is both useful and beautiful?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-018', 'Only straight lines and primary colours', 'De Stijl — Dutch for "the style" — was a movement founded in the Netherlands in 1917 by a group that included the painters Theo van Doesburg and Piet Mondrian. They reduced their work to essentials: horizontal and vertical lines, the three primary colours, and black, white and grey. The same approach was applied to furniture and buildings, most famously Gerrit Rietveld''s Red and Blue Chair.', 'art', 'designhistory', 'Wikipedia: De Stijl', 'https://en.wikipedia.org/wiki/De_Stijl', '{"quiz": {"question": "What does \"De Stijl\" mean?", "options": ["The square", "The style", "The line"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-019', 'When Paris fell for Japanese prints', 'After Japan reopened to foreign trade in the 1850s, its woodblock prints began arriving in Europe in large numbers. Artists in Paris were struck by their flat areas of colour, strong outlines and off-centre compositions. The resulting craze was called Japonisme. Van Gogh collected the prints and painted copies of them, and their influence can be seen in the work of Monet, Degas and Toulouse-Lautrec.', 'art', 'designhistory', 'Wikipedia: Japonisme', 'https://en.wikipedia.org/wiki/Japonisme', '{"quiz": {"question": "Which art form sparked Japonisme?", "options": ["Ink scrolls", "Woodblock prints", "Ceramics"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('art-020', 'The man who designed the first two minutes', 'Before the 1950s, film title sequences were usually plain lists of names. The graphic designer Saul Bass changed that. His animated opening for The Man with the Golden Arm in 1955, built around a jagged paper-cut arm, set the mood of the film before it began. He went on to create titles for Vertigo, North by Northwest and Psycho, as well as a number of well-known corporate logos.', 'art', 'designhistory', 'Wikipedia: Saul Bass', 'https://en.wikipedia.org/wiki/Saul_Bass', '{"quiz": null, "prompt": "Next time a film starts, watch the titles. What do they tell you to expect?", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-001', 'The first World Cup', 'The first FIFA World Cup was held in Uruguay in July 1930. Thirteen teams took part, all by invitation, and only four made the long sea voyage from Europe. Every match was played in the capital, Montevideo. The hosts, who were also the reigning Olympic champions, beat Argentina 4–2 in the final after trailing at half-time, and the following day was declared a national holiday.', 'sports', 'football', 'Wikipedia: 1930 FIFA World Cup', 'https://en.wikipedia.org/wiki/1930_FIFA_World_Cup', '{"quiz": {"question": "Who won the first World Cup?", "options": ["Brazil", "Argentina", "Uruguay"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-002', 'Cards inspired by traffic lights', 'Red and yellow cards were first used at the 1970 World Cup in Mexico. They were the idea of Ken Aston, an English referee who had seen how confusion over language could inflame a match. The story goes that the solution came to him while driving in London, as a traffic light changed: yellow for take care, red for stop. No player was sent off during that first tournament.', 'sports', 'football', 'Wikipedia: Penalty card', 'https://en.wikipedia.org/wiki/Penalty_card', '{"quiz": {"question": "At which World Cup were cards first used?", "options": ["1970", "1958", "1982"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-003', 'The day football got its rules', 'In late 1863, representatives of a handful of London clubs met at the Freemasons'' Tavern to agree a single set of rules for football. They formed the Football Association and published its first Laws of the Game that December. The main arguments were over carrying the ball and kicking opponents'' shins. Clubs that wanted to keep both went their own way, and their game became rugby.', 'sports', 'football', 'Wikipedia: Laws of the Game (association football)', 'https://en.wikipedia.org/wiki/Laws_of_the_Game_(association_football)', '{"quiz": {"question": "In which year was the Football Association founded?", "options": ["1863", "1901", "1848"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-004', 'A goalkeeper invented the penalty', 'The penalty kick was proposed by William McCrum, a goalkeeper and businessman from Milford in what is now Northern Ireland. He suggested it in 1890 as a way to punish defenders who deliberately fouled to stop a certain goal. Many at the time thought it ungentlemanly to assume a player would cheat on purpose. Football''s lawmakers adopted the idea the following year.', 'sports', 'football', 'Wikipedia: Penalty kick (association football)', 'https://en.wikipedia.org/wiki/Penalty_kick_(association_football)', '{"quiz": {"question": "What position did the inventor of the penalty play?", "options": ["Striker", "Referee", "Goalkeeper"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-005', 'Everyone plays everywhere', 'Total Football is a style of play in which any outfield player can take over the role of any other. When a defender runs forward, a team-mate drops into the space left behind, so the team''s shape holds while the individuals move. It is most closely linked to the Dutch club Ajax and the Netherlands team of the early 1970s, coached by Rinus Michels with Johan Cruyff as its star.', 'sports', 'football', 'Wikipedia: Total Football', 'https://en.wikipedia.org/wiki/Total_Football', '{"quiz": {"question": "Which country is most associated with Total Football?", "options": ["Brazil", "The Netherlands", "Italy"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-006', 'The first championship race', 'The Formula One World Championship began on 13 May 1950 at Silverstone, a former wartime airfield in England. The race was attended by King George VI. It was won by the Italian driver Giuseppe Farina in an Alfa Romeo, and Alfa Romeos filled the first three places. Farina went on to become the sport''s first world champion at the end of that season.', 'sports', 'f1', 'Wikipedia: 1950 British Grand Prix', 'https://en.wikipedia.org/wiki/1950_British_Grand_Prix', '{"quiz": {"question": "Where was the first championship race held?", "options": ["Monza", "Silverstone", "Monaco"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-007', 'Four tyres in two seconds', 'A modern Formula One pit stop is a rehearsed routine for around twenty mechanics. The car stops on its marks, is lifted at both ends, and all four wheels are removed and replaced. The fastest crews regularly do this in a little over two seconds, and the quickest stops on record have taken less than two. Refuelling during races has been banned since 2010, which is one reason stops became so short.', 'sports', 'f1', 'Wikipedia: Pit stop', 'https://en.wikipedia.org/wiki/Pit_stop', '{"quiz": {"question": "Since when has refuelling in races been banned?", "options": ["1994", "2021", "2010"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-008', 'Racing through city streets', 'The Monaco Grand Prix was first run in 1929 and is held on the ordinary streets of Monte Carlo and La Condamine. The circuit is the shortest and slowest on the Formula One calendar, with tight corners, a tunnel and almost no room to overtake. Barriers stand where other tracks have run-off areas, so a small mistake usually ends a driver''s race. A win here is counted among the sport''s great prizes.', 'sports', 'f1', 'Wikipedia: Monaco Grand Prix', 'https://en.wikipedia.org/wiki/Monaco_Grand_Prix', '{"quiz": {"question": "When was the Monaco Grand Prix first run?", "options": ["1966", "1950", "1929"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-009', 'The bar above the driver''s head', 'Since 2018 every Formula One car has carried a halo: a curved titanium bar that arches over the cockpit to protect the driver''s head from debris and impacts. It was unpopular at first, with drivers and fans alike complaining about how it looked. Opinions changed quickly after a series of serious accidents in which the device was credited with protecting drivers from grave injury.', 'sports', 'f1', 'Wikipedia: Halo (safety device)', 'https://en.wikipedia.org/wiki/Halo_(safety_device)', '{"quiz": {"question": "What is the halo made of?", "options": ["Carbon fibre only", "Steel", "Titanium"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-010', 'Why first place is worth 25', 'Formula One has changed its scoring many times. In the first season, 1950, only the top five finishers scored, with eight points for a win. The present system dates from 2010: the top ten score, on a scale of 25, 18, 15, 12, 10, 8, 6, 4, 2 and 1. The large gap between first and second was intended to make drivers race for the win and not settle for a safe second place.', 'sports', 'f1', 'Wikipedia: List of Formula One World Championship points scoring systems', 'https://en.wikipedia.org/wiki/List_of_Formula_One_World_Championship_points_scoring_systems', '{"quiz": {"question": "How many points does second place earn?", "options": ["20", "18", "15"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-011', 'Four laps, under four minutes', 'On 6 May 1954, at the Iffley Road track in Oxford, a 25-year-old medical student named Roger Bannister ran a mile in 3 minutes 59.4 seconds. He was the first person known to break four minutes, a mark some had thought beyond human reach. Two friends paced him through the early laps. His record stood for just forty-six days before the Australian John Landy ran faster.', 'sports', 'running', 'Wikipedia: Four-minute mile', 'https://en.wikipedia.org/wiki/Four-minute_mile', '{"quiz": {"question": "How long did Bannister''s record stand?", "options": ["A decade", "4 years", "46 days"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-012', 'Why a marathon is 42.195 km', 'Early Olympic marathons were roughly 40 kilometres long, and no two were the same. At the London Games of 1908 the course was laid out from Windsor Castle to the stadium, finishing in front of the royal box: 26 miles and 385 yards. In 1921 the sport''s governing body fixed that particular distance as the standard. It has been 42.195 kilometres ever since.', 'sports', 'running', 'Wikipedia: Marathon', 'https://en.wikipedia.org/wiki/Marathon', '{"quiz": {"question": "Which Olympics set the modern marathon distance?", "options": ["Paris 1924", "Athens 1896", "London 1908"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-013', 'A marathon in under two hours', 'On 12 October 2019, in a park in Vienna, the Kenyan runner Eliud Kipchoge covered the marathon distance in 1 hour 59 minutes 40 seconds. He was the first person to do so in under two hours. The run does not count as an official world record: it was a specially arranged event, with rotating teams of pacemakers and drinks handed over by bicycle, which the rules of open competition do not allow.', 'sports', 'running', 'Wikipedia: Ineos 1:59 Challenge', 'https://en.wikipedia.org/wiki/Ineos_1:59_Challenge', '{"quiz": {"question": "Why isn''t Kipchoge''s run an official record?", "options": ["It was run indoors", "Rotating pacemakers were used", "The course was too short"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-014', 'Thirteen runners in a park', 'On 2 October 2004, thirteen runners turned up in Bushy Park, south-west London, for a free, timed five-kilometre run organised by Paul Sinton-Hewitt. It was held again the following Saturday, and the one after that. The idea spread to other parks and then other countries, and became parkrun. It is still free, still run by volunteers, and open to walkers as much as runners.', 'sports', 'running', 'Wikipedia: Parkrun', 'https://en.wikipedia.org/wiki/Parkrun', '{"quiz": {"question": "How long is a parkrun?", "options": ["10 km", "A mile", "5 km"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-015', 'Gold without shoes', 'At the 1960 Olympic Games in Rome, the Ethiopian runner Abebe Bikila won the marathon running barefoot. He had been a late addition to the team, and the shoes available to him did not fit comfortably, so he ran as he had often trained. He finished in a world-record time under the torchlit Arch of Constantine. Four years later in Tokyo he won again — this time in shoes.', 'sports', 'running', 'Wikipedia: Abebe Bikila', 'https://en.wikipedia.org/wiki/Abebe_Bikila', '{"quiz": {"question": "In which city did Bikila win barefoot?", "options": ["Rome", "Mexico City", "Tokyo"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-016', 'The Games begin again', 'The first modern Olympic Games were held in Athens in April 1896, inspired by the ancient festival at Olympia and organised largely through the efforts of the Frenchman Pierre de Coubertin. Around 240 athletes took part, all of them men, from fourteen nations. Winners received a silver medal and an olive branch. Gold medals for first place were not introduced until later Games.', 'sports', 'general', 'Wikipedia: 1896 Summer Olympics', 'https://en.wikipedia.org/wiki/1896_Summer_Olympics', '{"quiz": {"question": "What did winners receive in 1896?", "options": ["A silver medal", "A laurel crown only", "A gold medal"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-017', 'Five rings, six colours', 'The Olympic rings were designed in 1913 by Pierre de Coubertin, founder of the modern Games. The five interlocking rings represent the five inhabited continents taking part, as they were then counted. No ring stands for a particular continent. The colours — blue, yellow, black, green and red, on a white background — were chosen because at least one of them appears in the flag of every nation.', 'sports', 'general', 'Wikipedia: Olympic symbols', 'https://en.wikipedia.org/wiki/Olympic_symbols', '{"quiz": {"question": "Who designed the Olympic rings?", "options": ["Carl Diem", "Otl Aicher", "Pierre de Coubertin"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-018', 'A game invented for a cold winter', 'In December 1891 James Naismith, an instructor at a training school in Springfield, Massachusetts, was asked to devise an indoor game to keep students active through the winter. He nailed two peach baskets to the gallery of the gymnasium and wrote thirteen rules. At first someone had to climb up and retrieve the ball after every score. Basketball spread quickly, and Naismith lived to see it played at the Olympics in 1936.', 'sports', 'general', 'Wikipedia: James Naismith', 'https://en.wikipedia.org/wiki/James_Naismith', '{"quiz": {"question": "What were the first basketball hoops?", "options": ["Barrel rings", "Fishing nets", "Peach baskets"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-019', 'The oldest tennis tournament', 'The first Wimbledon Championship was held in 1877 at the All England Croquet and Lawn Tennis Club, partly to raise money to repair the club''s pony-drawn roller. Twenty-two men entered, and the title was won by Spencer Gore. About two hundred spectators paid a shilling each to watch the final. It is the oldest tennis tournament in the world, and is still played on grass.', 'sports', 'general', 'Wikipedia: 1877 Wimbledon Championship', 'https://en.wikipedia.org/wiki/1877_Wimbledon_Championship', '{"quiz": {"question": "On what surface is Wimbledon played?", "options": ["Grass", "Hard court", "Clay"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('sports-020', 'Why the leader wears yellow', 'The Tour de France was created in 1903 by the sports newspaper L''Auto to boost its sales. In 1919 the organisers introduced a special jersey so that spectators could pick out the overall race leader as the riders passed. It was yellow, the colour of the paper on which L''Auto was printed. The newspaper is long gone; the maillot jaune remains cycling''s most famous prize.', 'sports', 'general', 'Wikipedia: Yellow jersey', 'https://en.wikipedia.org/wiki/Yellow_jersey', '{"quiz": {"question": "Why is the leader''s jersey yellow?", "options": ["It''s the colour of the sun", "Yellow dye was cheap", "The newspaper''s paper was yellow"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-001', 'Three hearts and blue blood', 'An octopus has three hearts. Two pump blood through its gills, and the third sends it round the rest of the body. That blood is blue: it carries oxygen using a copper-based protein called haemocyanin, where ours uses iron-based haemoglobin. Most of an octopus''s neurons are not in its head but in its eight arms, which can carry out some movements without detailed instructions from the brain.', 'nature', null, 'Wikipedia: Octopus', 'https://en.wikipedia.org/wiki/Octopus', '{"quiz": {"question": "How many hearts does an octopus have?", "options": ["Eight", "One", "Three"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-002', 'Directions given by dancing', 'When a honey bee finds a good patch of flowers, she returns to the hive and performs a waggle dance on the comb. The angle of her run, relative to straight up, shows the direction of the food relative to the Sun. The length of the waggle shows how far away it is. The Austrian scientist Karl von Frisch decoded the dance, and shared a Nobel Prize in 1973.', 'nature', null, 'Wikipedia: Waggle dance', 'https://en.wikipedia.org/wiki/Waggle_dance', '{"quiz": {"question": "What does the length of the waggle show?", "options": ["Time of day", "The type of flower", "Distance to the food"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-003', 'A tree older than the pyramids', 'In the White Mountains of California grows a Great Basin bristlecone pine known as Methuselah. Counting its growth rings showed it to be more than 4,800 years old, which means it was a seedling before the pyramids of Giza were built. Bristlecones grow extremely slowly in cold, dry, windy conditions, and their dense, resinous wood resists insects and rot. The tree''s exact location is kept secret to protect it.', 'nature', null, 'Wikipedia: Methuselah (pine tree)', 'https://en.wikipedia.org/wiki/Methuselah_(pine_tree)', '{"quiz": {"question": "Why is Methuselah''s location kept secret?", "options": ["It''s on private land", "To protect it", "Nobody recorded it"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-004', 'The bird that sees two summers', 'The Arctic tern breeds in the far north during the northern summer, then flies to the edge of Antarctica for the southern summer, and back again. It is the longest regular migration of any animal. Birds fitted with tiny tracking devices have been recorded travelling around 70,000 kilometres or more in a year. Because it follows the summer from pole to pole, the tern probably sees more daylight than any other creature.', 'nature', null, 'Wikipedia: Arctic tern', 'https://en.wikipedia.org/wiki/Arctic_tern', '{"quiz": {"question": "Between which regions does the Arctic tern migrate?", "options": ["Europe and Africa", "Arctic and Antarctic", "Asia and Australia"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-005', 'The salamander that regrows itself', 'The axolotl is a salamander from the lakes around Mexico City. Unlike most amphibians, it normally keeps its feathery external gills and stays in the water for its whole life, becoming an adult without ever taking the usual land-living form. It can also regenerate lost limbs, and even parts of its heart and spinal cord. Common in laboratories and aquariums, it is critically endangered in the wild.', 'nature', null, 'Wikipedia: Axolotl', 'https://en.wikipedia.org/wiki/Axolotl', '{"quiz": {"question": "Where do wild axolotls come from?", "options": ["The Amazon", "Japanese rivers", "Lakes near Mexico City"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-006', 'A journey no single butterfly completes', 'Each autumn, monarch butterflies from eastern North America fly up to several thousand kilometres to spend the winter clustered in mountain forests in central Mexico. In spring they head north again and lay eggs along the way. It takes several short-lived generations to finish the trip back. The butterflies that fly south the next autumn have never made the journey, yet find the same forests.', 'nature', null, 'Wikipedia: Monarch butterfly migration', 'https://en.wikipedia.org/wiki/Monarch_butterfly_migration', '{"quiz": {"question": "Where do eastern monarchs spend the winter?", "options": ["Florida", "Cuba", "Central Mexico"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-007', 'The only birds that fly backwards', 'Hummingbirds can hover in still air, and they are the only birds able to fly backwards as a matter of course. Their wings rotate at the shoulder and trace a figure of eight, producing lift on both the forward and the backward stroke. Smaller species beat their wings dozens of times every second. Fuelling this is demanding: a hummingbird may visit hundreds of flowers in a day.', 'nature', null, 'Wikipedia: Hummingbird', 'https://en.wikipedia.org/wiki/Hummingbird', '{"quiz": {"question": "What shape do a hummingbird''s wings trace?", "options": ["A figure of eight", "A straight line", "A circle"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-008', 'The network under the forest floor', 'Most trees live in partnership with fungi. Fine fungal threads wrap around or enter the tree''s roots and spread far into the soil, bringing back water and minerals; in return the tree supplies sugars. The same fungus can connect to many trees, forming what is called a mycorrhizal network. How much trees really exchange through these links is still actively debated among scientists.', 'nature', null, 'Wikipedia: Mycorrhizal network', 'https://en.wikipedia.org/wiki/Mycorrhizal_network', '{"quiz": null, "prompt": "On your next walk, look for mushrooms at the base of a tree. They''re the visible tip of something larger.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-009', 'The toughest animal is half a millimetre long', 'Tardigrades, also called water bears, are eight-legged animals usually less than a millimetre long. They live in moss, soil and water all over the world. When their surroundings dry out, they can curl into a dormant state and survive for years, then revive when water returns. In that state they have withstood extreme cold, intense radiation and even brief exposure to the vacuum of space.', 'nature', null, 'Wikipedia: Tardigrade', 'https://en.wikipedia.org/wiki/Tardigrade', '{"quiz": {"question": "What are tardigrades also called?", "options": ["Water bears", "Moss mites", "Sea monkeys"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-010', 'The largest animal that has ever lived', 'The blue whale is the largest animal known to have existed, heavier than any dinosaur yet discovered. Adults can reach around thirty metres in length. For all its size, it feeds almost entirely on krill, shrimp-like animals a few centimetres long, which it strains from huge mouthfuls of seawater through plates of baleen. A blue whale''s low-pitched calls can travel for hundreds of kilometres through the ocean.', 'nature', null, 'Wikipedia: Blue whale', 'https://en.wikipedia.org/wiki/Blue_whale', '{"quiz": {"question": "What do blue whales mainly eat?", "options": ["Squid", "Krill", "Fish"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-011', 'A crow that makes its own tools', 'The New Caledonian crow, found on islands in the South Pacific, is one of very few animals that manufacture tools. It trims twigs into hooks and cuts strips from the barbed edges of leaves, then uses them to pull grubs out of holes in wood. In laboratory tests, these crows have solved puzzles that require several steps in the right order.', 'nature', null, 'Wikipedia: New Caledonian crow', 'https://en.wikipedia.org/wiki/New_Caledonian_crow', '{"quiz": {"question": "What do the crows use their tools for?", "options": ["Building nests", "Extracting grubs", "Cracking shells"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-012', 'The colours were there all along', 'Leaves are green because of chlorophyll, the pigment that captures sunlight. They also contain yellow and orange pigments called carotenoids, hidden behind the green. In autumn, as days shorten, many trees stop making chlorophyll and break down what remains, and the yellows and oranges show through. Reds and purples are different: those pigments are newly made in autumn, from sugars trapped in the leaf.', 'nature', null, 'Wikipedia: Autumn leaf color', 'https://en.wikipedia.org/wiki/Autumn_leaf_color', '{"quiz": {"question": "Which autumn colours are newly made each year?", "options": ["Greens", "Reds and purples", "Yellows"], "answer": 1}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-013', 'The biggest tree on Earth', 'General Sherman is a giant sequoia in Sequoia National Park, California. It is not the tallest tree in the world, nor the widest, nor the oldest. But measured by the volume of wood in its trunk, it is the largest single-stem tree known. It stands about 84 metres tall and is estimated to be more than two thousand years old.', 'nature', null, 'Wikipedia: General Sherman (tree)', 'https://en.wikipedia.org/wiki/General_Sherman_(tree)', '{"quiz": {"question": "By what measure is General Sherman the largest tree?", "options": ["Age", "Trunk volume", "Height"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-014', 'Cities of the sea', 'Coral reefs are built over centuries by colonies of tiny animals called polyps, which lay down skeletons of limestone. Most reef-building corals depend on microscopic algae living inside their tissues, which supply food made from sunlight. Reefs cover well under one per cent of the ocean floor, yet they are home to roughly a quarter of all known marine species.', 'nature', null, 'Wikipedia: Coral reef', 'https://en.wikipedia.org/wiki/Coral_reef', '{"quiz": {"question": "What are corals?", "options": ["Animals", "Rocks", "Plants"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-015', 'Fathers on the ice', 'Emperor penguins breed during the Antarctic winter, the coldest season in the coldest place on Earth. After the female lays a single egg, she returns to the sea to feed. The male balances the egg on his feet under a fold of skin for about two months, without eating. The males huddle together against the wind, taking turns to shuffle from the cold outer edge into the warmer middle.', 'nature', null, 'Wikipedia: Emperor penguin', 'https://en.wikipedia.org/wiki/Emperor_penguin', '{"quiz": {"question": "Who incubates the emperor penguin''s egg?", "options": ["The male", "The female", "Both, in shifts"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-016', 'Grass that grows as you watch', 'Bamboo is a giant grass, and some species are among the fastest-growing plants in the world. Under ideal conditions, certain kinds have been recorded growing around ninety centimetres in a single day. A new bamboo shoot emerges from the ground at its full width and reaches its full height in one growing season; after that the stem never gets any thicker or taller.', 'nature', null, 'Wikipedia: Bamboo', 'https://en.wikipedia.org/wiki/Bamboo', '{"quiz": {"question": "What kind of plant is bamboo?", "options": ["A tree", "A grass", "A fern"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-017', 'Young sunflowers follow the sun', 'Growing sunflowers turn through the day, facing east at dawn and tracking the sun to the west, then swinging back overnight. The movement comes from uneven growth on opposite sides of the stem, timed by the plant''s internal clock. Once a sunflower is mature and in bloom, it stops moving and settles facing east. East-facing flowers warm up faster in the morning and attract more pollinators.', 'nature', null, 'Wikipedia: Helianthus', 'https://en.wikipedia.org/wiki/Helianthus', '{"quiz": {"question": "Which way do mature sunflowers usually face?", "options": ["South", "East", "West"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-018', 'A forest that is one tree', 'In Utah there is a stand of quaking aspen known as Pando, Latin for "I spread". Its roughly forty thousand trunks look like separate trees, but they are genetically identical and grow from a single shared root system. Pando covers about forty hectares, and is counted among the heaviest known living organisms. It is thought to be thousands of years old, although its exact age is uncertain.', 'nature', null, 'Wikipedia: Pando (tree)', 'https://en.wikipedia.org/wiki/Pando_(tree)', '{"quiz": {"question": "What does \"Pando\" mean?", "options": ["I spread", "Many trunks", "Old one"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-019', 'Two lives in one', 'The grey-green crust on a rock or tree trunk is not a single organism. A lichen is a partnership between a fungus and an alga or cyanobacterium. The fungus provides structure and holds water; its partner makes food from sunlight. Together they can live where neither could alone, on bare rock, Arctic tundra and desert. Many lichens are sensitive to air pollution, so their presence can be a sign of clean air.', 'nature', null, 'Wikipedia: Lichen', 'https://en.wikipedia.org/wiki/Lichen', '{"quiz": null, "prompt": "Find a lichen on a wall, pavement or tree today. What colour is it?", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('nature-020', 'Lights in the dark', 'Fireflies are beetles that make their own light through a chemical reaction in their abdomens. A substance called luciferin reacts with oxygen, helped by an enzyme, luciferase. Almost all of the energy is released as light and very little as heat. Each species flashes in its own pattern, which males and females use to find one another on summer evenings.', 'nature', null, 'Wikipedia: Firefly', 'https://en.wikipedia.org/wiki/Firefly', '{"quiz": {"question": "What kind of insect is a firefly?", "options": ["A fly", "A beetle", "A moth"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-001', 'The 20-20-20 habit', 'Long stretches at a screen can leave eyes feeling tired and dry, partly because people blink less while concentrating. Eye-care organisations suggest a simple habit: every twenty minutes, look at something about twenty feet away for twenty seconds. The break lets the focusing muscles of the eye relax. It is a comfort measure, not a treatment — persistent problems are worth raising with an optician.', 'health', null, 'American Optometric Association: Computer vision syndrome', 'https://www.aoa.org/healthy-eyes/eye-and-vision-conditions/computer-vision-syndrome', '{"quiz": null, "prompt": "Try it now: find something across the room or out of a window and look at it for twenty seconds.", "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-002', 'How much movement is recommended', 'The World Health Organization recommends that adults do at least 150 minutes of moderate-intensity physical activity across a week, or at least 75 minutes of vigorous activity, along with muscle-strengthening activity on two or more days. Moderate means your breathing quickens but you can still talk — a brisk walk counts. The guidance also stresses that any amount of activity is better than none.', 'health', null, 'WHO: Physical activity', 'https://www.who.int/news-room/fact-sheets/detail/physical-activity', '{"quiz": {"question": "How much moderate activity does the WHO recommend weekly for adults?", "options": ["At least 600 minutes", "At least 30 minutes", "At least 150 minutes"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-003', 'Twenty seconds at the sink', 'Washing hands with soap and water is one of the simplest ways to avoid spreading germs. Public-health guidance is to wet your hands, lather them with soap — including the backs, between the fingers and under the nails — and scrub for at least twenty seconds before rinsing and drying. Twenty seconds is about the time it takes to hum "Happy Birthday" twice.', 'health', null, 'Wikipedia: Hand washing', 'https://en.wikipedia.org/wiki/Hand_washing', '{"quiz": {"question": "How long should you scrub your hands?", "options": ["5 seconds", "2 minutes", "At least 20 seconds"], "answer": 2}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-004', 'The doctor who asked colleagues to wash', 'In 1847 Ignaz Semmelweis, a doctor in Vienna, noticed that far more women died of fever in a maternity ward staffed by doctors than in one staffed by midwives. The doctors often came straight from carrying out autopsies. He required them to wash their hands in a chlorine solution, and deaths fell sharply. His findings were widely rejected at the time; germ theory would explain them only years later.', 'health', null, 'Wikipedia: Ignaz Semmelweis', 'https://en.wikipedia.org/wiki/Ignaz_Semmelweis', '{"quiz": {"question": "What did Semmelweis ask doctors to do?", "options": ["Open windows", "Wear masks", "Wash their hands"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-005', 'Where 10,000 steps came from', 'The target of ten thousand steps a day did not begin as medical advice. In the mid-1960s a Japanese company sold a pedometer called the manpo-kei, which translates roughly as "ten-thousand-step meter", and the round number caught on. Research since then suggests that benefits begin at step counts well below that figure, and that moving more than you currently do is what matters most.', 'health', null, 'Wikipedia: Pedometer', 'https://en.wikipedia.org/wiki/Pedometer', '{"quiz": {"question": "Where did the 10,000-step target originate?", "options": ["A pedometer''s name in Japan", "A WHO guideline", "An Olympic training plan"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-006', 'Sleep comes in cycles', 'A night''s sleep is not one even state. Sleepers pass repeatedly through stages of lighter sleep, deep sleep and rapid-eye-movement sleep, in which most vivid dreaming happens. Each cycle lasts very roughly ninety minutes, and a typical night contains four to six of them. Deep sleep is concentrated early in the night, while the periods of REM sleep grow longer towards morning.', 'health', null, 'Wikipedia: Sleep cycle', 'https://en.wikipedia.org/wiki/Sleep_cycle', '{"quiz": {"question": "Roughly how long is one sleep cycle?", "options": ["4 hours", "90 minutes", "20 minutes"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-007', 'Your internal clock runs on light', 'Most living things have a circadian rhythm, an internal cycle of roughly twenty-four hours that influences sleepiness, body temperature and hormone levels. In people, the master clock is a small cluster of cells in the brain that receives signals directly from the eyes. Light is the main cue that keeps it in step with the day, which is why crossing time zones leaves the body temporarily out of sync.', 'health', null, 'Wikipedia: Circadian rhythm', 'https://en.wikipedia.org/wiki/Circadian_rhythm', '{"quiz": null, "prompt": "Step outside or stand by a window for a few minutes of daylight this morning.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-008', 'The eight-glasses idea', 'The advice to drink eight glasses of water a day is widely repeated, but reviews of the evidence have found no solid scientific basis for that specific number. Water needs vary with body size, activity, climate and health, and a good deal of the water people take in comes from food and other drinks. For most healthy people, thirst is a reasonable guide. Medical conditions can change that, so individual advice matters.', 'health', null, 'Wikipedia: Drinking water', 'https://en.wikipedia.org/wiki/Drinking_water', '{"quiz": {"question": "Is there strong evidence for exactly eight glasses a day?", "options": ["No", "Yes", "Only for athletes"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-009', 'Bathing in the forest', 'In 1982 Japan''s forestry ministry coined the term shinrin-yoku, or "forest bathing", to encourage people to spend unhurried time among trees. Nothing is required beyond walking slowly and paying attention with all the senses. Studies have linked time in green spaces with lower reported stress, though researchers are still working out how strong and lasting the effects are.', 'health', null, 'Wikipedia: Nature therapy', 'https://en.wikipedia.org/wiki/Nature_therapy', '{"quiz": null, "prompt": "Find the nearest tree or patch of green and spend two unhurried minutes there.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-010', 'How long coffee stays with you', 'Caffeine works largely by blocking the action of adenosine, a substance that builds up in the brain during waking hours and promotes sleepiness. Its effects fade slowly. In healthy adults it takes very roughly five hours for the body to clear half of a dose, with wide variation from person to person. That is why an afternoon coffee can still be at work at bedtime.', 'health', null, 'Wikipedia: Caffeine', 'https://en.wikipedia.org/wiki/Caffeine', '{"quiz": {"question": "How does caffeine keep you alert?", "options": ["It adds sugar to the blood", "It raises body temperature", "It blocks adenosine"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-011', 'What the number on sunscreen means', 'SPF stands for sun protection factor, and it describes protection against UVB, the rays mainly responsible for sunburn. In laboratory terms, SPF 30 lets through about one thirtieth of the burning radiation, which means it filters roughly 97 per cent; SPF 50 filters about 98 per cent. In practice, protection depends heavily on applying enough and reapplying it, especially after swimming or sweating.', 'health', null, 'Wikipedia: Sunscreen', 'https://en.wikipedia.org/wiki/Sunscreen', '{"quiz": {"question": "What does SPF mainly measure protection against?", "options": ["Visible light", "Heat", "UVB rays"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-012', 'Two minutes, twice a day', 'Dental guidance in many countries is consistent and simple: brush your teeth with fluoride toothpaste twice a day, for about two minutes each time. One of those should be last thing at night. After brushing, spit out the excess toothpaste but don''t rinse with water straight away, since rinsing washes away the fluoride that helps protect the enamel.', 'health', null, 'NHS: How to keep your teeth clean', 'https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/', '{"quiz": {"question": "After brushing, the guidance is to…", "options": ["Spit, don''t rinse", "Rinse thoroughly", "Brush again"], "answer": 0}, "prompt": null, "evergreen": true}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-013', 'The tomato timer', 'In the late 1980s an Italian student, Francesco Cirillo, began using a tomato-shaped kitchen timer to help him study. He would work on one task for twenty-five minutes, then take a short break, with a longer rest after four rounds. He called each interval a pomodoro, the Italian for tomato. Many people find that a short, fixed stretch makes a daunting task easier to begin.', 'health', null, 'Wikipedia: Pomodoro Technique', 'https://en.wikipedia.org/wiki/Pomodoro_Technique', '{"quiz": {"question": "What does \"pomodoro\" mean?", "options": ["Pause", "Tomato", "Timer"], "answer": 1}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-014', 'Eight weeks of paying attention', 'In 1979 Jon Kabat-Zinn started a programme at the University of Massachusetts Medical School for patients living with chronic pain and stress. Over eight weeks it taught them to pay deliberate attention to their breathing, body and thoughts, without judging what they noticed. It became known as mindfulness-based stress reduction. The course has since been widely studied and taught around the world.', 'health', null, 'Wikipedia: Mindfulness-based stress reduction', 'https://en.wikipedia.org/wiki/Mindfulness-based_stress_reduction', '{"quiz": null, "prompt": "Take three slow breaths and notice where you feel each one.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-015', 'The runner''s high', 'Some people feel a brief lift in mood, with less anxiety and less sense of effort, after sustained exercise. This runner''s high was long put down to endorphins. More recent research suggests that endocannabinoids, substances the body makes that can pass from the blood into the brain, may play a larger part. Not everyone experiences it, and it is not needed for exercise to be worthwhile.', 'health', null, 'Wikipedia: Neurobiological effects of physical exercise', 'https://en.wikipedia.org/wiki/Neurobiological_effects_of_physical_exercise', '{"quiz": {"question": "Which substances are now thought to play a large part in the runner''s high?", "options": ["Vitamin D", "Caffeine", "Endocannabinoids"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-016', 'Vitamin from sunlight', 'Vitamin D is unusual among vitamins because the body can make it. When ultraviolet B rays from sunlight reach the skin, they convert a compound there into a form the body turns into vitamin D, which helps regulate calcium and keep bones healthy. How much is made depends on the season, latitude, time of day and skin tone. Food and supplements are the other sources.', 'health', null, 'Wikipedia: Vitamin D', 'https://en.wikipedia.org/wiki/Vitamin_D', '{"quiz": {"question": "What does vitamin D help the body regulate?", "options": ["Calcium", "Iron", "Blood sugar"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-017', 'A short nap, on purpose', 'A brief daytime nap can reduce sleepiness and improve alertness for a while afterwards. Naps of around ten to twenty minutes are often suggested, because they are over before the sleeper sinks into deep sleep. Waking from deep sleep tends to bring grogginess, known as sleep inertia. Napping late in the day can also make it harder to fall asleep at night.', 'health', null, 'Wikipedia: Nap', 'https://en.wikipedia.org/wiki/Nap', '{"quiz": {"question": "What is the grogginess after waking called?", "options": ["Sleep inertia", "Sleep debt", "Microsleep"], "answer": 0}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-018', 'Why we yawn is still a puzzle', 'Everybody yawns, and so do many other animals, yet science has no settled explanation for it. The old idea that a yawn brings in extra oxygen has not held up in experiments. Another proposal is that yawning helps cool the brain. What is well established is that yawns are contagious: seeing, hearing or even reading about one can set off another.', 'health', null, 'Wikipedia: Yawn', 'https://en.wikipedia.org/wiki/Yawn', '{"quiz": null, "prompt": "Did you yawn while reading this? Many people do.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-019', 'Fibre, the overlooked nutrient', 'Dietary fibre is the part of plant foods that the body cannot fully digest. It is found in wholegrains, beans, lentils, vegetables, fruit, nuts and seeds. Health guidance in the United Kingdom is for adults to aim for about thirty grams a day, and most people eat considerably less. Increasing fibre gradually, and drinking enough fluid alongside it, tends to be more comfortable.', 'health', null, 'NHS: How to get more fibre into your diet', 'https://www.nhs.uk/live-well/eat-well/digestive-health/how-to-get-more-fibre-into-your-diet/', '{"quiz": {"question": "About how much fibre a day does UK guidance suggest for adults?", "options": ["100 g", "5 g", "30 g"], "answer": 2}, "prompt": null, "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
insert into public.discovery_cards (id, headline, content, category, subcategory, source_title, source_url, interaction, content_version, status) values ('health-020', 'Writing down what went well', 'A gratitude journal is a simple practice: regularly noting a few things you are thankful for, however small. In studies, people asked to do this have tended to report somewhat higher wellbeing than comparison groups, although the effects are generally modest and vary between individuals. It costs a minute or two and a line of writing, and it asks only that you notice.', 'health', null, 'Wikipedia: Gratitude journal', 'https://en.wikipedia.org/wiki/Gratitude_journal', '{"quiz": null, "prompt": "Name one thing from the last day that you''re glad happened.", "evergreen": false}'::jsonb, 1, 'published') on conflict (id) do update set headline = excluded.headline, content = excluded.content, source_title = excluded.source_title, source_url = excluded.source_url, interaction = excluded.interaction, content_version = excluded.content_version;
